[workspace] resolver = "2" members = [ "crates/swarm-core", "crates/swarm-llm", "crates/swarm-watchdog", "crates/swarm-worker", "crates/swarm-cli", "crates/swarm-planner", "crates/swarm-reviewer", ]
[workspace.package] version = "0.1.0" edition = "2021" rust-version = "1.94.1" license = "MIT"
[workspace.dependencies] postgres = { version = "0.19", features = [ "with-uuid-1", "with-serde_json-1", ] } thiserror = "1.0" uuid = { version = "1.10", features = ["v4", "v5", "serde"] } serde = { version = "1.0", features = ["derive"] } serde_json = "1.0" tracing = "0.1" tracing-subscriber = { version = "0.3", features = ["env-filter", "json"] } clap = { version = "4.5", features = ["derive"] } sha2 = "0.10" ctrlc = "3.4" aws-config = "1" aws-credential-types = "1" aws-sdk-s3 = "1" aws-types = "1" tokio = { version = "1", features = ["rt-multi-thread"] }

[package]
name = "swarm-cli"
version.workspace = true
edition.workspace = true

[dependencies]
swarm-core = { path = "../swarm-core" }
clap = { workspace = true }
uuid = { workspace = true }
serde_json = { workspace = true }

//! CLI: seed / status / review / reopen / unblock.

use std::process::ExitCode;

use clap::{Parser, Subcommand};
use swarm_core::{Budget, Needs, SwarmDispatcher, TaskContract, Verdict};
use uuid::Uuid;

#[derive(Parser)]
#[command(name = "swarm-cli", version, about = "Swarm Dispatcher CLI")]
struct Cli {
    #[command(subcommand)]
    command: Cmd,
}

#[derive(Subcommand)]
enum Cmd {
    /// Создать демо-граф: корень + 2 зависимые задачи.
    Seed,
    /// Показать все задачи.
    Status,
    /// Оставить ревью.
    Review {
        task_id: Uuid,
        artifact_ref: String,
        #[arg(value_parser = ["approve", "changes", "reject"])]
        verdict: String,
        /// JSON-массив реально наблюдённых проверок.
        ///
        /// Обязателен для `approve`: CLI не выдумывает проходящий набор
        /// checks (иначе строгий review-gate в `submit_review` обходится
        /// фиктивным успехом). Для `changes`/`reject` не нужен.
        #[arg(long)]
        checks: Option<String>,
    },
    /// Переоткрыть завершённую задачу (каскадный откат).
    Reopen { task_id: Uuid, actor: String },
    /// Разблокировать задачу.
    Unblock { task_id: Uuid, actor: String },
}

fn main() -> ExitCode {
    let cli = Cli::parse();

    let dsn = match std::env::var("DATABASE_URL") {
        Ok(v) => v,
        Err(_) => {
            eprintln!("error: DATABASE_URL required");
            return ExitCode::FAILURE;
        }
    };
    let mut d = match SwarmDispatcher::connect(&dsn) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("error: connect to Postgres: {e}");
            return ExitCode::FAILURE;
        }
    };

    // Ненулевой код возврата на любой ошибке: вызывающие скрипты не должны
    // принимать неуспех за успех (аудит: exit-code семантика CLI).
    let outcome: Result<(), String> = match cli.command {
        Cmd::Seed => seed(&mut d),
        Cmd::Status => status(&mut d),
        Cmd::Review {
            task_id,
            artifact_ref,
            verdict,
            checks,
        } => review(&mut d, task_id, &artifact_ref, &verdict, checks.as_deref()),
        Cmd::Reopen { task_id, actor } => match d.reopen(task_id, &actor) {
            Ok(n) => {
                println!("blocked {n} descendants");
                Ok(())
            }
            Err(e) => Err(e.to_string()),
        },
        Cmd::Unblock { task_id, actor } => match d.unblock(task_id, &actor) {
            Ok(state) => {
                println!("new state: {state}");
                Ok(())
            }
            Err(e) => Err(e.to_string()),
        },
    };

    match outcome {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

/// Оставить ревью.
///
/// Набор проверок (`--checks`) приходит от оператора и не выдумывается: для
/// `approve` он обязателен, иначе CLI отказывает (fail-closed). Это закрывает
/// обход строгого review-gate в `submit_review`, который раньше «проходил» на
/// жёстко зашитом `[{"type":"cmd","status":"pass"}]` независимо от контракта.
fn review(
    d: &mut SwarmDispatcher,
    task_id: Uuid,
    artifact_ref: &str,
    verdict: &str,
    checks_json: Option<&str>,
) -> Result<(), String> {
    let v = match verdict {
        "approve" => Verdict::Approved,
        "changes" => Verdict::ChangesRequested,
        _ => Verdict::Rejected,
    };

    let checks = match checks_json {
        Some(raw) => {
            let parsed: serde_json::Value = serde_json::from_str(raw)
                .map_err(|e| format!("--checks is not valid JSON: {e}"))?;
            if !parsed.is_array() {
                return Err("--checks must be a JSON array".to_string());
            }
            parsed
        }
        None if verdict == "approve" => {
            return Err(
                "approve requires --checks <json>: the CLI will not fabricate a \
                 passing check set; supply the checks actually observed"
                    .to_string(),
            );
        }
        None => serde_json::json!([]),
    };

    match d.submit_review(task_id, artifact_ref, "cli-reviewer", v, &checks) {
        Ok(state) => {
            println!("new state: {state}");
            Ok(())
        }
        Err(e) => Err(e.to_string()),
    }
}

fn contract(kind: &str) -> TaskContract {
    TaskContract {
        kind: kind.to_string(),
        description: None,
        checks: vec![serde_json::json!({"type": "cmd", "run": "true"})],
        needs: Needs::default(),
        budget: Budget::default(),
    }
}

fn seed(d: &mut SwarmDispatcher) -> Result<(), String> {
    let root = Uuid::new_v4();
    d.add_task(root, &contract("root"), None, 10_000, 10)
        .map_err(|e| format!("add root: {e}"))?;

    for i in 1..=2 {
        let child = Uuid::new_v4();
        d.add_task(
            child,
            &contract(&format!("child-{i}")),
            Some(root),
            10_000,
            5,
        )
        .map_err(|e| format!("add child: {e}"))?;
        d.add_dep(child, root)
            .map_err(|e| format!("add dep: {e}"))?;
        println!("created child {} depends on root {}", child, root);
    }
    println!("seed done, root = {root}");
    Ok(())
}

fn status(d: &mut SwarmDispatcher) -> Result<(), String> {
    // Чтение через task_status(): прямой SELECT к tasks сервисным ролям закрыт
    // после roles.sql.
    let tasks = d.list_task_status(200).map_err(|e| e.to_string())?;

    if tasks.is_empty() {
        println!("(no tasks)");
        return Ok(());
    }

    println!(
        "{:<38} {:<10} {:<8} {:<10} {:>4} {:>4}",
        "id", "state", "epoch", "owner", "att", "rw"
    );
    for t in tasks {
        println!(
            "{:<38} {:<10} {:<8} {:<10} {:>4} {:>4}",
            t.id,
            t.state,
            t.lease_epoch,
            t.owner.as_deref().unwrap_or("-"),
            t.attempts,
            t.rework,
        );
        if let Some(reason) = t.block_reason {
            println!("    blocked: {reason}");
        }
    }
    Ok(())
}

//! Интеграционные тесты CLI (Волна 5.2): exit-коды и fail-closed review.
//!
//! Дефект, который эти тесты закрывают: `swarm-cli` (205 строк) и
//! `swarm-watchdog` (84 строки) не имели НИ ОДНОГО теста, хотя именно CLI
//! минтит review и exit-коды, которые читают скрипты-вызывающие.
//!
//! Тесты запускают СОБРАННЫЙ бинарь как процесс и проверяют реальный
//! exit-код/вывод (не внутренние функции) — это то, что видит потребитель.
//!
//! Требует TEST_DATABASE_URL с детерминированной БД (disposable, prefix
//! c2_/v0/test_) и применённой схемы + roles. Без DSN тесты падают явно
//! (FIND-08: не молчаливый пропуск).

use std::process::Command;

fn dsn() -> String {
    std::env::var("TEST_DATABASE_URL").unwrap_or_else(|_| {
        panic!(
            "BLOCKED/FAIL: TEST_DATABASE_URL не задан; CLI-тесты требуют живую \
             тестовую БД (prefix test_/v0/c2_)"
        )
    })
}

/// Путь к собранному бинарю CLI (cargo передаёт его в env для integration-тестов).
fn cli_bin() -> String {
    env!("CARGO_BIN_EXE_swarm-cli").to_string()
}

fn run_cli(args: &[&str]) -> (i32, String, String) {
    let out = Command::new(cli_bin())
        .args(args)
        .env("DATABASE_URL", dsn())
        .output()
        .expect("failed to spawn swarm-cli");
    (
        out.status.code().unwrap_or(-1),
        String::from_utf8_lossy(&out.stdout).to_string(),
        String::from_utf8_lossy(&out.stderr).to_string(),
    )
}

/// Без DATABASE_URL CLI обязан упасть с ненулевым кодом и понятным сообщением.
#[test]
fn cli_requires_database_url() {
    let out = Command::new(cli_bin())
        .arg("status")
        .env_remove("DATABASE_URL")
        .output()
        .expect("spawn");
    assert!(
        !out.status.success(),
        "без DATABASE_URL должен быть ненулевой код"
    );
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(
        err.contains("DATABASE_URL"),
        "сообщение должно упоминать DATABASE_URL, получено: {err}"
    );
}

/// `status` на живой БД: успех, код 0, печатает состояние.
#[test]
fn cli_status_succeeds_on_live_db() {
    let (code, stdout, stderr) = run_cli(&["status"]);
    assert_eq!(code, 0, "status должен вернуть 0; stderr={stderr}");
    assert!(!stdout.trim().is_empty(), "status должен что-то напечатать");
}

/// Fail-closed: `review --verdict approve` БЕЗ --checks обязан отказать
/// (CLI не выдумывает проходной набор проверок).
/// Проверяем на несуществующем task_id: отказ должен наступить ДО обращения
/// к БД за ревью — по причине отсутствия checks.
#[test]
fn cli_review_approve_without_checks_is_rejected() {
    let fake = "00000000-0000-0000-0000-000000000000";
    let (code, _stdout, stderr) = run_cli(&["review", fake, "sha256:deadbeef", "approve"]);
    assert_ne!(code, 0, "approve без --checks должен дать ненулевой код");
    assert!(
        stderr.contains("--checks"),
        "сообщение должно требовать --checks, получено: {stderr}"
    );
}

/// `--checks` должен быть валидным JSON-массивом.
#[test]
fn cli_review_rejects_non_array_checks() {
    let fake = "00000000-0000-0000-0000-000000000000";
    let (code, _stdout, stderr) = run_cli(&[
        "review",
        fake,
        "sha256:deadbeef",
        "approve",
        "--checks",
        "{\"not\":\"an array\"}",
    ]);
    assert_ne!(code, 0, "не-массив --checks должен быть отклонён");
    assert!(
        stderr.contains("array"),
        "сообщение должно говорить про JSON array, получено: {stderr}"
    );
}

/// `reopen` на несуществующей задаче: ошибка -> ненулевой код (не молчаливый успех).
#[test]
fn cli_reopen_unknown_task_fails() {
    let fake = "00000000-0000-0000-0000-000000000000";
    let (code, _stdout, stderr) = run_cli(&["reopen", fake, "op"]);
    assert_ne!(
        code, 0,
        "reopen неизвестной задачи должен упасть; stderr={stderr}"
    );
}

/// `unblock` на несуществующей задаче: ошибка -> ненулевой код.
#[test]
fn cli_unblock_unknown_task_fails() {
    let fake = "00000000-0000-0000-0000-000000000000";
    let (code, _stdout, stderr) = run_cli(&["unblock", fake, "op"]);
    assert_ne!(
        code, 0,
        "unblock неизвестной задачи должен упасть; stderr={stderr}"
    );
}

[package]
name = "swarm-core"
version.workspace = true
edition.workspace = true

[dependencies]
postgres = { workspace = true }
thiserror = { workspace = true }
uuid = { workspace = true }
serde = { workspace = true }
serde_json = { workspace = true }

[dev-dependencies]

[[test]]
name = "integration_alt"
path = "tests/alt/integration_alt.rs"

use crate::errors::DispatcherError;
use crate::types::{Lease, TaskContract, TaskRow, TaskStatusRow, Verdict};
use postgres::{Client, NoTls};
use uuid::Uuid;

pub struct SwarmDispatcher {
    client: Client,
}

impl SwarmDispatcher {
    /// Единственный `?`-совместимый путь к `postgres::Error` — явный `map_err`.
    /// Никогда не полагаться на `From<postgres::Error>` (см. комментарий в `errors.rs`).
    pub fn connect(dsn: &str) -> Result<Self, DispatcherError> {
        let client = Client::connect(dsn, NoTls).map_err(DispatcherError::from_pg)?;
        Ok(Self { client })
    }

    // ---------- чтение ----------

    /// Список задач **напрямую из таблицы** — доступно только суперпользователю
    /// (тесты). Сервисные роли читают через [`SwarmDispatcher::list_task_status`].
    pub fn list_tasks(
        &mut self,
        filter_state: Option<&str>,
        limit: i64,
    ) -> Result<Vec<TaskRow>, DispatcherError> {
        let rows = match filter_state {
            Some(state) => self
                .client
                .query(
                    "SELECT id, root_id, state, lease_owner, lease_epoch, \
                            attempts, rework, priority, block_reason \
                     FROM tasks WHERE state = $1 \
                     ORDER BY priority DESC, created_at ASC LIMIT $2",
                    &[&state, &limit],
                )
                .map_err(DispatcherError::from_pg)?,
            None => self
                .client
                .query(
                    "SELECT id, root_id, state, lease_owner, lease_epoch, \
                            attempts, rework, priority, block_reason \
                     FROM tasks \
                     ORDER BY priority DESC, created_at ASC LIMIT $1",
                    &[&limit],
                )
                .map_err(DispatcherError::from_pg)?,
        };

        Ok(rows
            .iter()
            .map(|r| TaskRow {
                id: r.get(0),
                root_id: r.get(1),
                state: r.get(2),
                owner: r.get(3),
                lease_epoch: r.get(4),
                attempts: r.get(5),
                rework: r.get(6),
                priority: r.get(7),
                block_reason: r.get(8),
            })
            .collect())
    }

    /// Список задач через `task_status(n)` — путь чтения для сервисных ролей.
    /// Прямой SELECT к `tasks` после `roles.sql` им закрыт.
    pub fn list_task_status(&mut self, limit: i32) -> Result<Vec<TaskStatusRow>, DispatcherError> {
        let rows = self
            .client
            .query(
                "SELECT id, root_id, state, lease_epoch, lease_owner, \
                        attempts, rework, block_reason \
                 FROM task_status($1)",
                &[&limit],
            )
            .map_err(DispatcherError::from_pg)?;

        Ok(rows
            .iter()
            .map(|r| TaskStatusRow {
                id: r.get(0),
                root_id: r.get(1),
                state: r.get(2),
                lease_epoch: r.get(3),
                owner: r.get(4),
                attempts: r.get(5),
                rework: r.get(6),
                block_reason: r.get(7),
            })
            .collect())
    }

    // ---------- граф ----------

    pub fn add_task(
        &mut self,
        task_id: Uuid,
        contract: &TaskContract,
        root_id: Option<Uuid>,
        budget_cap: i64,
        priority: i32,
    ) -> Result<(), DispatcherError> {
        contract.validate()?;
        let body = serde_json::to_value(contract)?;
        self.client
            .execute(
                "SELECT add_task($1, $2, $3::jsonb, $4, $5)",
                &[&task_id, &root_id, &body, &budget_cap, &priority],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(())
    }

    pub fn add_dep(&mut self, task_id: Uuid, dep_id: Uuid) -> Result<(), DispatcherError> {
        self.client
            .execute("SELECT add_dep($1, $2)", &[&task_id, &dep_id])
            .map_err(DispatcherError::from_pg)?;
        Ok(())
    }

    pub fn promote_ready(&mut self) -> Result<i32, DispatcherError> {
        let row = self
            .client
            .query_one("SELECT promote_ready()", &[])
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    // ---------- воркеры ----------

    pub fn register_worker(
        &mut self,
        worker_id: &str,
        capabilities: &serde_json::Value,
        tags: &[String],
    ) -> Result<(), DispatcherError> {
        self.client
            .execute(
                "SELECT register_worker($1, $2::jsonb, $3)",
                &[&worker_id, capabilities, &tags],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(())
    }

    /// Выдаёт аренду. Контракт возвращается **сырым JSON** — разбор только через
    /// [`Lease::typed_contract`]. См. комментарий к `Lease` в `types.rs`.
    pub fn claim(
        &mut self,
        worker_id: &str,
        lease_sec: i32,
    ) -> Result<Option<Lease>, DispatcherError> {
        let rows = self
            .client
            .query(
                "SELECT out_task_id, out_contract, out_epoch, out_budget, out_spent \
                 FROM claim_task($1, $2)",
                &[&worker_id, &lease_sec],
            )
            .map_err(DispatcherError::from_pg)?;
        if rows.is_empty() {
            return Ok(None);
        }
        let r = &rows[0];
        let task_id: Uuid = r.get(0);
        let epoch: i64 = r.get(2);
        // FIND-CODE-02: контур обратной связи. Отдельный RPC, а не лишние
        // колонки `claim_task`: смена возвращаемого типа ломает применение
        // миграций (`create or replace` не меняет row type) и требует DROP +
        // перевыдачи гранта. Здесь же — обычный вызов привилегированной
        // функции, доступный только держателю живой аренды.
        let (rework, last_review) = self.rework_feedback(task_id, worker_id, epoch)?;
        Ok(Some(Lease {
            task_id,
            contract: r.get(1), // сырой JSON: никакого from_value здесь
            epoch,
            budget_cap: r.get(3),
            spent_tokens: r.get(4),
            worker_id: worker_id.to_owned(),
            rework,
            last_review,
        }))
    }

    /// FIND-CODE-02: диагностика последнего ревью для возвращённой задачи.
    /// Возвращает `(rework, last_review)`; при отсутствии ревью — `(n, None)`.
    /// `task_rework_feedback` — SECURITY DEFINER с проверкой аренды и identity,
    /// поэтому чужой воркер не прочтёт диагностику чужой задачи.
    fn rework_feedback(
        &mut self,
        task_id: Uuid,
        worker_id: &str,
        epoch: i64,
    ) -> Result<(i32, Option<serde_json::Value>), DispatcherError> {
        let rows = self
            .client
            .query(
                "SELECT out_rework, out_last_review \
                 FROM task_rework_feedback($1, $2, $3)",
                &[&task_id, &worker_id, &epoch],
            )
            .map_err(DispatcherError::from_pg)?;
        if rows.is_empty() {
            return Ok((0, None));
        }
        let r = &rows[0];
        Ok((r.get(0), r.get(1)))
    }

    /// F8: свежее состояние бюджета задачи (локальный + по дереву).
    ///
    /// `Lease.spent_tokens` — снимок на момент claim; перед вызовом LLM воркер
    /// обязан видеть расход, сделанный после выдачи (в т.ч. по тому же дереву).
    /// Возвращает `(spent, budget_cap, root_spent, root_budget_cap)`;
    /// `root_budget_cap` = `None`, если лимита по дереву нет.
    pub fn task_budget_state(
        &mut self,
        task_id: Uuid,
    ) -> Result<(i64, i64, i64, Option<i64>), DispatcherError> {
        let row = self
            .client
            .query_one(
                "SELECT out_spent, out_budget, out_root_spent, out_root_budget \
                 FROM task_budget_state($1)",
                &[&task_id],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok((row.get(0), row.get(1), row.get(2), row.get(3)))
    }

    /// Не бросает исключение при потере аренды — возвращает `Ok(false)`.
    /// Так воркер может реагировать на потерю без `catch`.
    pub fn heartbeat(&mut self, lease: &Lease, extend_sec: i32) -> Result<bool, DispatcherError> {
        let row = self
            .client
            .query_one(
                "SELECT heartbeat($1, $2, $3, $4)",
                &[&lease.task_id, &lease.worker_id, &lease.epoch, &extend_sec],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    pub fn save_artifact(
        &mut self,
        lease: &Lease,
        artifact_ref: &str,
        storage_path: &str,
        content_type: Option<&str>,
        size_bytes: Option<i64>,
    ) -> Result<(), DispatcherError> {
        self.client
            .execute(
                "SELECT save_artifact($1, $2, $3, $4, $5, $6, $7)",
                &[
                    &lease.task_id,
                    &lease.worker_id,
                    &lease.epoch,
                    &artifact_ref,
                    &storage_path,
                    &content_type,
                    &size_bytes,
                ],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(())
    }

    /// Возвращает новое состояние задачи: `"review"` или `"blocked"`.
    pub fn complete(
        &mut self,
        lease: &Lease,
        result_ref: &str,
        tokens: i64,
    ) -> Result<String, DispatcherError> {
        let row = self
            .client
            .query_one(
                "SELECT complete_task($1, $2, $3, $4, $5)",
                &[
                    &lease.task_id,
                    &lease.worker_id,
                    &lease.epoch,
                    &result_ref,
                    &tokens,
                ],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    /// F4: честный отказ воркера. Переводит задачу в `blocked` с `reason`,
    /// без подделки `spent_tokens` (раньше это делалось через `complete`
    /// с overspend). Возвращает `"blocked"`.
    pub fn fail(
        &mut self,
        lease: &Lease,
        result_ref: Option<&str>,
        reason: &str,
    ) -> Result<String, DispatcherError> {
        let row = self
            .client
            .query_one(
                "SELECT fail_task($1, $2, $3, $4, $5)",
                &[
                    &lease.task_id,
                    &lease.worker_id,
                    &lease.epoch,
                    &result_ref,
                    &reason,
                ],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    /// Issue #3: отказ воркера с явным целевым состоянием.
    ///
    /// Отличается от [`SwarmDispatcher::fail`] тем, что состояние не жёстко
    /// `blocked`, а выбирается вызывающим: `budget_exhausted` (исчерпан бюджет)
    /// или `failed` (сбой авторизации — нужна ротация ключа). Причина всё
    /// равно пишется в `block_reason`, а событие — в журнал.
    pub fn fail_with_state(
        &mut self,
        lease: &Lease,
        result_ref: Option<&str>,
        reason: &str,
        state: &str,
    ) -> Result<String, DispatcherError> {
        let row = self
            .client
            .query_one(
                "SELECT fail_task_state($1, $2, $3, $4, $5, $6)",
                &[
                    &lease.task_id,
                    &lease.worker_id,
                    &lease.epoch,
                    &result_ref,
                    &reason,
                    &state,
                ],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    // ---------- ревью ----------

    /// Возвращает новое состояние задачи: `"done"`, `"ready"` или `"blocked"`.
    pub fn submit_review(
        &mut self,
        task_id: Uuid,
        artifact_ref: &str,
        reviewer: &str,
        verdict: Verdict,
        checks: &serde_json::Value,
    ) -> Result<String, DispatcherError> {
        let row = self
            .client
            .query_one(
                "SELECT submit_review($1, $2, $3, $4, $5::jsonb)",
                &[
                    &task_id,
                    &artifact_ref,
                    &reviewer,
                    &verdict.as_str(),
                    checks,
                ],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    // ---------- сторож ----------

    pub fn reclaim_expired(&mut self) -> Result<i32, DispatcherError> {
        let row = self
            .client
            .query_one("SELECT reclaim_expired()", &[])
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    // ---------- Issue #2: Cost ledger ----------

    /// Записать метрики LLM-вызова для точного учёта расходов.
    #[allow(clippy::too_many_arguments)]
    pub fn record_llm_call(
        &mut self,
        task_id: Uuid,
        worker_id: &str,
        lease_epoch: i64,
        model: &str,
        provider: &str,
        prompt_tokens: i64,
        completion_tokens: i64,
        cached_tokens: i64,
        prompt_cost_usd: f64,
        completion_cost_usd: f64,
        started_at: &str,
        completed_at: &str,
        duration_ms: i64,
        success: bool,
        error_code: Option<&str>,
        error_message: Option<&str>,
        http_status: Option<i32>,
    ) -> Result<(), DispatcherError> {
        let total_cost = prompt_cost_usd + completion_cost_usd;
        self.client
            .execute(
                "INSERT INTO llm_calls \
                 (task_id, worker_id, lease_epoch, model, provider, \
                  prompt_tokens, completion_tokens, cached_tokens, \
                  prompt_cost_usd, completion_cost_usd, total_cost_usd, \
                  started_at, completed_at, duration_ms, success, error_code, error_message, \
                  http_status) \
                 VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9::float8::numeric, $10::float8::numeric, $11::float8::numeric, $12::text::timestamptz, $13::text::timestamptz, $14, $15, $16, $17, $18)",
                &[
                    &task_id,
                    &worker_id,
                    &lease_epoch,
                    &model,
                    &provider,
                    &prompt_tokens,
                    &completion_tokens,
                    &cached_tokens,
                    &prompt_cost_usd,
                    &completion_cost_usd,
                    &total_cost,
                    &started_at,
                    &completed_at,
                    &duration_ms,
                    &success,
                    &error_code,
                    &error_message,
                    &http_status,
                ],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(())
    }

    /// Issue #26: кандидаты на ревью через `review_candidates(n)`.
    ///
    /// Путь чтения для роли `swarm_reviewer`: прямой SELECT на `tasks`/`artifacts`
    /// ей закрыт (least privilege), витрина — SECURITY DEFINER.
    pub fn review_candidates(
        &mut self,
        limit: i32,
    ) -> Result<Vec<crate::types::ReviewCandidate>, DispatcherError> {
        let rows = self
            .client
            .query(
                "SELECT id, result_ref, contract, storage_path, created_by \
                 FROM review_candidates($1)",
                &[&limit],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(rows
            .iter()
            .map(|r| crate::types::ReviewCandidate {
                id: r.get(0),
                result_ref: r.get(1),
                contract: r.get(2),
                storage_path: r.get(3),
                created_by: r.get(4),
            })
            .collect())
    }

    /// Issue #3: суммарная стоимость всех LLM-вызовов (USD) из cost ledger.
    ///
    /// Используется hard budget guard перед каждым вызовом модели. Считается
    /// в микродолларах (целые), чтобы не терять мелкие расходы на f64.
    pub fn total_cost_usd(&mut self) -> Result<f64, DispatcherError> {
        let row = self
            .client
            .query_one(
                "SELECT COALESCE(SUM(total_cost_usd), 0)::float8 FROM llm_calls",
                &[],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    // ---------- операторские ----------

    pub fn reopen(&mut self, task_id: Uuid, actor: &str) -> Result<i32, DispatcherError> {
        let row = self
            .client
            .query_one("SELECT reopen_task($1, $2)", &[&task_id, &actor])
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    pub fn unblock(&mut self, task_id: Uuid, actor: &str) -> Result<String, DispatcherError> {
        let row = self
            .client
            .query_one("SELECT unblock_task($1, $2)", &[&task_id, &actor])
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    pub fn verify_chain(&mut self, task_id: Uuid) -> Result<bool, DispatcherError> {
        let row = self
            .client
            .query_one("SELECT verify_chain($1)", &[&task_id])
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }
}

// ---------- транзакции ----------
// Два лайфтайма обязательны: `&'a mut Transaction<'a>` делает заём бесконечным
// (инвариантность), и `tx.commit()` после замыкания не компилируется (E0597/E0505).
pub struct DispatcherTx<'a, 'b> {
    tx: &'a mut postgres::Transaction<'b>,
}

impl SwarmDispatcher {
    /// Всё или ничего: `Err` из замыкания (или паника) = rollback, `Ok` = commit.
    pub fn with_transaction<F, T>(&mut self, f: F) -> Result<T, DispatcherError>
    where
        F: FnOnce(&mut DispatcherTx<'_, '_>) -> Result<T, DispatcherError>,
    {
        let mut tx = self
            .client
            .transaction()
            .map_err(DispatcherError::from_pg)?;
        let out = {
            let mut w = DispatcherTx { tx: &mut tx };
            f(&mut w)? // при Err tx дропается без commit -> rollback
        };
        tx.commit().map_err(DispatcherError::from_pg)?;
        Ok(out)
    }
}

impl DispatcherTx<'_, '_> {
    pub fn add_task(
        &mut self,
        task_id: Uuid,
        contract: &TaskContract,
        root_id: Option<Uuid>,
        budget_cap: i64,
        priority: i32,
    ) -> Result<(), DispatcherError> {
        contract.validate()?;
        let body = serde_json::to_value(contract)?;
        self.tx
            .execute(
                "SELECT add_task($1, $2, $3::jsonb, $4, $5)",
                &[&task_id, &root_id, &body, &budget_cap, &priority],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(())
    }

    pub fn add_dep(&mut self, task_id: Uuid, dep_id: Uuid) -> Result<(), DispatcherError> {
        self.tx
            .execute("SELECT add_dep($1, $2)", &[&task_id, &dep_id])
            .map_err(DispatcherError::from_pg)?;
        Ok(())
    }

    pub fn promote_ready(&mut self) -> Result<i32, DispatcherError> {
        let row = self
            .tx
            .query_one("SELECT promote_ready()", &[])
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }
}

//! ПРАВИЛО: `postgres::Error` НЕ конвертируется через `?`/`#[from]`.
//!
//! У варианта `Database` стоит `#[source]`, а не `#[from]`. Иначе любой
//! будущий `?` на `postgres::Error` молча превратит доменную ошибку
//! (`LeaseLost`, `CycleDetected`, …) в общий `Database`, и маппинг SQLSTATE
//! будет обойдён. Любой `?` на ошибке postgres обязан идти явно:
//!
//! ```text
//! self.client.query_one(...).map_err(DispatcherError::from_pg)?;
//! Client::connect(dsn, NoTls).map_err(DispatcherError::from_pg)?;
//! ```

use thiserror::Error;

/// Полная иерархия ошибок диспетчера.
///
/// Соответствие SQLSTATE → вариант зафиксировано в `from_sqlstate`.
/// Добавление нового SQLSTATE требует добавления варианта и теста.
#[derive(Debug, Error)]
pub enum DispatcherError {
    #[error("lease lost or expired")]
    LeaseLost,

    #[error("artifact not found")]
    ArtifactMissing,

    #[error("contract invalid")]
    ContractInvalid,

    #[error("task not found")]
    TaskNotFound,

    #[error("dependency cycle")]
    CycleDetected,

    #[error("depth limit exceeded")]
    DepthExceeded,

    #[error("fanout limit exceeded")]
    FanoutExceeded,

    #[error("task limit exceeded")]
    TaskLimitExceeded,

    #[error("task is not in 'done' state")]
    NotDone,

    #[error("root task not found")]
    RootNotFound,

    #[error("dependency spans different roots")]
    CrossRootDependency,

    #[error("task is not in 'pending' state")]
    TaskNotPending,

    #[error("task is not in 'blocked' state")]
    NotBlocked,

    #[error("review is stale (wrong artifact or state)")]
    ReviewStale,

    #[error("self-review is not allowed")]
    SelfReview,

    #[error("acceptance checks failed")]
    ChecksFailed,

    #[error("worker capabilities are invalid")]
    WorkerInvalid,

    #[error("worker is not registered")]
    WorkerUnknown,

    #[error("database error")]
    Database(#[source] postgres::Error),

    #[error("serialization error")]
    Serialization(#[from] serde_json::Error),
}

impl DispatcherError {
    /// Маппинг ошибки `postgres` в доменную ошибку по SQLSTATE.
    ///
    /// Если SQLSTATE неизвестен — возвращаем как есть.
    pub fn from_pg(e: postgres::Error) -> Self {
        if let Some(db) = e.as_db_error() {
            if let Some(known) = Self::from_sqlstate(db.code().code()) {
                return known;
            }
        }
        Self::Database(e)
    }

    fn from_sqlstate(code: &str) -> Option<Self> {
        Some(match code {
            "LS001" => Self::LeaseLost,
            "AR001" => Self::ArtifactMissing,
            "CT001" => Self::ContractInvalid,
            "GR000" => Self::TaskNotFound,
            "GR001" => Self::CycleDetected,
            "GR002" => Self::DepthExceeded,
            "GR003" => Self::FanoutExceeded,
            "GR004" => Self::TaskLimitExceeded,
            "GR005" => Self::NotDone,
            "GR006" => Self::RootNotFound,
            "GR007" => Self::CrossRootDependency,
            "GR008" => Self::TaskNotPending,
            "GR009" => Self::NotBlocked,
            "RV001" => Self::ReviewStale,
            "RV002" => Self::SelfReview,
            "RV003" => Self::ChecksFailed,
            "WK001" => Self::WorkerInvalid,
            "WK002" => Self::WorkerUnknown,
            _ => return None,
        })
    }

    pub fn is_transient(&self) -> bool {
        // Сериализация/дедлоки Postgres. В v0 ретраев нет — заготовка.
        matches!(self, Self::Database(e)
            if matches!(e.code().map(|c| c.code()), Some("40001" | "40P01")))
    }

    /// `insufficient_privilege` (42501): роли не хватает гранта на функцию/таблицу.
    ///
    /// Нужно вызывающему, который хочет отличить «нет прав читать» от
    /// «нет данных» — например, Planner под ролью `swarm_planner` без гранта
    /// на `task_status`.
    pub fn is_insufficient_privilege(&self) -> bool {
        matches!(self, Self::Database(e)
            if e.code().map(|c| c.code() == "42501").unwrap_or(false))
    }

    /// `unique_violation` (23505): вставка конфликтует с существующей строкой.
    ///
    /// Для Planner это сигнал идемпотентного пропуска: граф с таким `root_id`
    /// уже создан (актуально, когда читать `task_status` роли не разрешено).
    pub fn is_unique_violation(&self) -> bool {
        matches!(self, Self::Database(e)
            if e.code().map(|c| c.code() == "23505").unwrap_or(false))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sqlstate_known_codes_map() {
        // Проверяем именно маппинг SQLSTATE → вариант, а не текст сообщения.
        use DispatcherError::*;
        let cases: [(&str, fn(&DispatcherError) -> bool); 18] = [
            ("LS001", |e| matches!(e, LeaseLost)),
            ("AR001", |e| matches!(e, ArtifactMissing)),
            ("CT001", |e| matches!(e, ContractInvalid)),
            ("GR000", |e| matches!(e, TaskNotFound)),
            ("GR001", |e| matches!(e, CycleDetected)),
            ("GR002", |e| matches!(e, DepthExceeded)),
            ("GR003", |e| matches!(e, FanoutExceeded)),
            ("GR004", |e| matches!(e, TaskLimitExceeded)),
            ("GR005", |e| matches!(e, NotDone)),
            ("GR006", |e| matches!(e, RootNotFound)),
            ("GR007", |e| matches!(e, CrossRootDependency)),
            ("GR008", |e| matches!(e, TaskNotPending)),
            ("GR009", |e| matches!(e, NotBlocked)),
            ("RV001", |e| matches!(e, ReviewStale)),
            ("RV002", |e| matches!(e, SelfReview)),
            ("RV003", |e| matches!(e, ChecksFailed)),
            ("WK001", |e| matches!(e, WorkerInvalid)),
            ("WK002", |e| matches!(e, WorkerUnknown)),
        ];
        for (code, is_expected) in cases {
            let e = DispatcherError::from_sqlstate(code)
                .unwrap_or_else(|| panic!("sqlstate {code} not mapped"));
            assert!(
                is_expected(&e),
                "sqlstate {code} mapped to wrong variant: {e:?}"
            );
        }
    }

    #[test]
    fn sqlstate_unknown_returns_none() {
        assert!(DispatcherError::from_sqlstate("99999").is_none());
        assert!(DispatcherError::from_sqlstate("").is_none());
        assert!(DispatcherError::from_sqlstate("XX000").is_none());
    }
}

pub mod dispatcher;
pub mod errors;
pub mod types;

pub use dispatcher::{DispatcherTx, SwarmDispatcher};
pub use errors::DispatcherError;
pub use types::{Budget, Lease, Needs, TaskContract, TaskRow, TaskState, TaskStatusRow, Verdict};

use crate::errors::DispatcherError;
use serde::{Deserialize, Serialize};
use uuid::Uuid;

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct Needs {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub min_ram_gb: Option<f64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub coder_class: Option<f64>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub affinity_tags: Vec<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Budget {
    #[serde(default = "default_attempts")]
    pub attempts: u32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_rework: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_depth: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_children: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_tasks: Option<u32>,
}

fn default_attempts() -> u32 {
    3
}

impl Default for Budget {
    fn default() -> Self {
        Self {
            attempts: default_attempts(),
            max_rework: None,
            max_depth: None,
            max_children: None,
            max_tasks: None,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TaskContract {
    pub kind: String,
    /// Текст задачи от пользователя (через Planner). Пробрасывается воркеру,
    /// чтобы LLM знал, что именно делать. Помечается как недоверенный ввод
    /// в промпте воркера (`<untrusted>`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    /// Непустой массив check-ов. Интерпретируется воркером, схема проверяет только форму.
    pub checks: Vec<serde_json::Value>,
    #[serde(default)]
    pub needs: Needs,
    #[serde(default)]
    pub budget: Budget,
}

impl TaskContract {
    /// Локальная валидация формы. Совпадает по строгости с SQL-валидацией:
    /// что отклоняем здесь — отклонил бы и SQL. SQL остаётся источником истины.
    pub fn validate(&self) -> Result<(), DispatcherError> {
        if self.kind.trim().is_empty()
            || self.checks.is_empty()
            || self.budget.attempts == 0
            || self
                .needs
                .min_ram_gb
                .is_some_and(|v| !v.is_finite() || v < 0.0)
            || self
                .needs
                .coder_class
                .is_some_and(|v| !v.is_finite() || v < 0.0)
        {
            return Err(DispatcherError::ContractInvalid);
        }
        Ok(())
    }
}

/// Аренда, возвращённая из `claim_task`. Frozen-семантика на стороне вызывающего.
///
/// `contract` хранится как **сырой JSON**, а не как `TaskContract`: SQL
/// принимает контракты, которые Rust-тип не разберёт (без `kind`, с дробным
/// `budget.attempts`). Если бы `claim` десериализовал контракт сразу после
/// выдачи аренды, задача зависла бы в `leased` на весь срок аренды, затем
/// `reclaim_expired` сжёг бы попытку, и через `attempts` попыток задача ушла
/// бы в `blocked`. Разбор — только явно, через [`Lease::typed_contract`].
#[derive(Debug, Clone)]
pub struct Lease {
    pub task_id: Uuid,
    pub contract: serde_json::Value,
    pub epoch: i64,
    pub budget_cap: i64,
    pub spent_tokens: i64,
    pub worker_id: String,
    /// FIND-CODE-02: число возвратов задачи на доработку. `> 0` означает, что
    /// предыдущая попытка была отвергнута ревьюером.
    pub rework: i32,
    /// FIND-CODE-02: диагностика последнего ревью
    /// (`{verdict, artifact_ref, checks, reviewer}`) или `null`, если ревью
    /// ещё не было. Воркер при `rework > 0` обязан подложить это в промпт,
    /// иначе он перегенерирует то же решение вслепую (корень
    /// `changes_requested = 39` на проде).
    pub last_review: Option<serde_json::Value>,
}

impl Lease {
    /// Типизированный разбор контракта. **Не влияет на аренду** — вызывается
    /// только тем, кому нужен типизированный доступ к полям контракта.
    pub fn typed_contract(&self) -> Result<TaskContract, DispatcherError> {
        let contract: TaskContract = serde_json::from_value(self.contract.clone())
            .map_err(DispatcherError::Serialization)?;
        contract.validate()?;
        Ok(contract)
    }
}

/// Вердикт ревьюера.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verdict {
    Approved,
    ChangesRequested,
    Rejected,
}

impl Verdict {
    pub fn as_str(&self) -> &'static str {
        match self {
            Verdict::Approved => "approved",
            Verdict::ChangesRequested => "changes_requested",
            Verdict::Rejected => "rejected",
        }
    }
}

/// Состояния задачи. Соответствует CHECK в схеме.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TaskState {
    Pending,
    Ready,
    Leased,
    Review,
    Done,
    Blocked,
    /// Issue #3: исчерпан бюджет (токен-лимит или глобальный).
    BudgetExhausted,
    /// Issue #3: необратимый сбой (например, авторизация 401/403).
    Failed,
}

impl TaskState {
    pub fn as_str(&self) -> &'static str {
        match self {
            TaskState::Pending => "pending",
            TaskState::Ready => "ready",
            TaskState::Leased => "leased",
            TaskState::Review => "review",
            TaskState::Done => "done",
            TaskState::Blocked => "blocked",
            TaskState::BudgetExhausted => "budget_exhausted",
            TaskState::Failed => "failed",
        }
    }

    pub fn parse(s: &str) -> Option<Self> {
        Some(match s {
            "pending" => TaskState::Pending,
            "ready" => TaskState::Ready,
            "leased" => TaskState::Leased,
            "review" => TaskState::Review,
            "done" => TaskState::Done,
            "blocked" => TaskState::Blocked,
            "budget_exhausted" => TaskState::BudgetExhausted,
            "failed" => TaskState::Failed,
            _ => return None,
        })
    }
}

/// Строка функции `task_status()` — путь чтения, доступный сервисным ролям
