#[test]
fn concurrent_claims_are_disjoint() {
    reset();
    let mut setup = d();
    for i in 0..8 {
        worker(&mut setup, &format!("w{i}"));
    }
    for _ in 0..24 {
        setup
            .add_task(Uuid::new_v4(), &contract(), None, 1000, 0)
            .unwrap();
    }
    setup.promote_ready().unwrap();
    let got = Arc::new(Mutex::new(Vec::new()));
    let hs: Vec<_> = (0..8)
        .map(|i| {
            let got = got.clone();
            std::thread::spawn(move || {
                let mut d = d();
                while let Some(l) = d.claim(&format!("w{i}"), 60).unwrap() {
                    got.lock().unwrap().push(l.task_id);
                }
            })
        })
        .collect();
    for h in hs {
        h.join().unwrap();
    }
    let mut v = got.lock().unwrap().clone();
    assert_eq!(v.len(), 24);
    v.sort();
    v.dedup();
    assert_eq!(v.len(), 24);
}

/// Контракт, который SQL принимает (kind не обязателен, число может быть дробным),
/// но который Rust не может десериализовать ПОСЛЕ того, как аренда уже выдана.
///
/// F15: проверки обязаны иметь непустой строковый type, поэтому «непонятность для
/// Rust» несёт дробный budget.attempts (2.5), а не малформед-проверка.
#[test]
fn contract_accepted_by_sql_but_not_by_rust_must_not_strand_the_task() {
    reset();
    let mut d = d();
    worker(&mut d, "w1");
    let t = Uuid::new_v4();
    raw()
        .execute(
            "select add_task($1, null, $2::jsonb, 100, 0)",
            &[
                &t,
                &json!({"checks":[{"type":"cmd","run":"true"}], "budget":{"attempts": 2.5}}),
            ],
        )
        .unwrap();
    d.promote_ready().unwrap();
    let r = d.claim("w1", 3600);
    let state: String = raw()
        .query_one("select state from tasks where id=$1", &[&t])
        .unwrap()
        .get(0);
    eprintln!(
        "claim result: {:?}; task state afterwards: {state}",
        r.as_ref().map(|_| "lease").map_err(|e| e.to_string())
    );
    assert!(
        r.is_ok(),
        "claim failed after lease was already granted -> task stuck in '{state}' for an hour"
    );
}

fn count(ids: &[Uuid]) -> i64 {
    raw()
        .query_one(
            "select count(*) from tasks where id = any($1)",
            &[&ids.to_vec()],
        )
        .unwrap()
        .get(0)
}

#[test]
fn with_transaction_rolls_back_on_error() {
    reset();
    let mut d = d();
    let (a, b) = (Uuid::new_v4(), Uuid::new_v4());
    let r = d.with_transaction(|tx| {
        tx.add_task(a, &contract(), None, 100, 0)?;
        assert_eq!(
            count(&[a]),
            0,
            "uncommitted insert must be invisible to other connections"
        );
        let mut bad = contract();
        bad.checks.clear();
        tx.add_task(b, &bad, None, 100, 0)?; // локальная валидация -> Err
        Ok(())
    });
    assert!(matches!(r, Err(DispatcherError::ContractInvalid)));
    assert_eq!(count(&[a, b]), 0);
}

#[test]
fn with_transaction_rolls_back_on_sql_error_midway() {
    reset();
    let mut d = d();
    let (a, b) = (Uuid::new_v4(), Uuid::new_v4());
    let r = d.with_transaction(|tx| {
        tx.add_task(a, &contract(), None, 100, 0)?;
        tx.add_task(b, &contract(), Some(a), 100, 0)?;
        tx.add_dep(b, a)?;
        tx.add_dep(a, b)?; // цикл (SQL GR001 или GR008) -> откат всех трёх
        Ok(())
    });
    assert!(r.is_err());
    assert_eq!(count(&[a, b]), 0);
}

#[test]
fn with_transaction_commits_whole_graph_atomically() {
    reset();
    let mut d = d();
    let ids: Vec<Uuid> = (0..4).map(|_| Uuid::new_v4()).collect();
    let n = d
        .with_transaction(|tx| {
            tx.add_task(ids[0], &contract(), None, 100, 0)?;
            for w in ids.windows(2) {
                tx.add_task(w[1], &contract(), Some(ids[0]), 100, 0)?;
                tx.add_dep(w[1], w[0])?;
            }
            tx.promote_ready()
        })
        .unwrap();
    assert_eq!(n, 1); // готов только корень
    assert_eq!(count(&ids), 4);
}

// ---------------------------------------------------------------------------
// Волна 5.2: перенесены 5 тестов из устаревшего `integration.rs`.
//
// `integration.rs` был ранней копией этого файла; после F15 (строгая форма
// checks) он устарел, но его уникальные проверки оставались нужны и при этом
// были спрятаны за `#[ignore]` — т.е. НЕ выполнялись ни harness, ни мутациями
// (найдено ночным прогоном). Уникальные тесты перенесены сюда БЕЗ `#[ignore]`;
// устаревшие дубли (contract_*_strand, concurrent_claims, with_transaction_*)
// в этом файле уже есть в актуальной форме.
// ---------------------------------------------------------------------------

/// add_task создаёт задачу в pending и list_tasks её возвращает.
#[test]
fn add_task_and_list() {
    reset();
    let mut d = d();
    let id = Uuid::new_v4();
    d.add_task(id, &contract(), None, 1000, 5).unwrap();
    let rows = d.list_tasks(None, 10).unwrap();
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0].id, id);
    assert_eq!(rows[0].state, "pending");
    assert_eq!(rows[0].priority, 5);
}

/// Цикл в зависимостях отклоняется (GR00x).
#[test]
fn add_dep_cycle_rejected() {
    reset();
    let mut d = d();
    let a = Uuid::new_v4();
    let b = Uuid::new_v4();
    d.add_task(a, &contract(), None, 1000, 0).unwrap();
    d.add_task(b, &contract(), Some(a), 1000, 0).unwrap();
    d.add_dep(b, a).unwrap();
    let err = d.add_dep(a, b).unwrap_err();
    assert!(
        matches!(err, DispatcherError::CycleDetected),
        "got: {err:?}"
    );
}

/// claim выдаёт lease с epoch=1, повторный claim пуст, артефакт с чужим epoch
/// отклоняется (fencing).
#[test]
fn claim_and_fencing() {
    reset();
    let mut d = d();
    worker(&mut d, "w1");
    let id = ready_task(&mut d);

    let lease = d.claim("w1", 300).unwrap().expect("lease");
    assert_eq!(lease.task_id, id);
    assert_eq!(lease.epoch, 1);
    assert!(d.claim("w1", 300).unwrap().is_none(), "задача уже занята");

    d.save_artifact(&lease, "sha256:aaa", "/tmp/a", None, None)
        .unwrap();

    let mut stale = lease.clone();
    stale.epoch = 0;
    let err = d
        .save_artifact(&stale, "sha256:bbb", "/tmp/b", None, None)
        .unwrap_err();
    assert!(matches!(err, DispatcherError::LeaseLost));
}

/// self-review отклоняется (RV00x), сторонний рецензент переводит в done.
#[test]
fn complete_and_review_self_rejected() {
    reset();
    let mut d = d();
    worker(&mut d, "w1");
    let id = ready_task(&mut d);
    let lease = d.claim("w1", 300).unwrap().unwrap();
    d.save_artifact(&lease, "sha256:x", "/tmp/x", None, None)
        .unwrap();
    assert_eq!(d.complete(&lease, "sha256:x", 10).unwrap(), "review");

    let checks = json!([{"type": "cmd", "run": "true", "status": "pass"}]);
    let err = d
        .submit_review(id, "sha256:x", "w1", Verdict::Approved, &checks)
        .unwrap_err();
    assert!(matches!(err, DispatcherError::SelfReview));

    let state = d
        .submit_review(id, "sha256:x", "reviewer", Verdict::Approved, &checks)
        .unwrap();
    assert_eq!(state, "done");
}

/// Хеш-цепочка остаётся валидной после полного цикла операций.
#[test]
fn verify_chain_after_operations() {
    reset();
    let mut d = d();
    worker(&mut d, "w1");
    let id = ready_task(&mut d);
    let lease = d.claim("w1", 300).unwrap().unwrap();
    d.save_artifact(&lease, "sha256:x", "/tmp/x", None, None)
        .unwrap();
    d.complete(&lease, "sha256:x", 10).unwrap();
    assert!(d.verify_chain(id).unwrap());
}

[package]
name = "swarm-llm"
version.workspace = true
edition.workspace = true
description = "Общий LLM-клиент (sync): openai / anthropic / openai-compatible / mock"

[dependencies]
reqwest = { version = "0.12", features = ["json", "blocking", "rustls-tls"] }
serde = { workspace = true }
serde_json = { workspace = true }
thiserror = { workspace = true }

//! Ошибки LLM-клиента.

use thiserror::Error;

#[derive(Debug, Error)]
pub enum LlmError {
    #[error("llm config error: {0}")]
    Config(String),

    #[error("llm transport error: {0}")]
    Transport(String),

    #[error("llm http error: status={status} body={body}")]
    Http { status: u16, body: String },

    #[error("llm response is not valid json: {0}")]
    InvalidJson(String),

    #[error("llm request timed out")]
    Timeout,
}

impl LlmError {
    /// Транзиентная ошибка — имеет смысл повторить (сеть, 5xx, 429, таймаут).
    pub fn is_transient(&self) -> bool {
        match self {
            LlmError::Timeout => true,
            LlmError::Transport(_) => true,
            LlmError::Http { status, .. } => *status >= 500 || *status == 429,
            _ => false,
        }
    }

    /// HTTP-статус, если ошибка HTTP.
    pub fn status(&self) -> Option<u16> {
        match self {
            LlmError::Http { status, .. } => Some(*status),
            _ => None,
        }
    }
}

pub type Result<T> = std::result::Result<T, LlmError>;

//! Общий LLM-клиент (sync, `reqwest::blocking`).
//!
//! Провайдеры: `openai`, `anthropic`, `openai-compatible` (алиас `relayfast`),
//! `mock` (ответ из файла — для тестов).
//!
//! Вынесен из `swarm-planner` в отдельный crate (ТЗ v0.3 §2), чтобы Planner и
//! LLM-worker использовали один и тот же клиент без дублирования.

use serde::{Deserialize, Serialize};

pub mod error;

pub use error::LlmError;

/// Конфигурация LLM, читается из env.
#[derive(Debug, Clone)]
pub struct LlmConfig {
    pub provider: String,
    pub api_key: Option<String>,
    pub model: String,
    pub base_url: Option<String>,
    pub max_retries: u32,
    pub max_tokens: u32,
    pub mock_file: Option<String>,
    /// Таймаут одного HTTP-запроса, секунды.
    pub timeout_sec: u64,
}

impl LlmConfig {
    /// Читает конфигурацию из env с заданным префиксом (по умолчанию `LLM_`).
    ///
    /// Для обратной совместимости с Planner поддерживается префикс `PLANNER_LLM_`.
    pub fn from_env_prefixed(prefix: &str) -> Result<Self, LlmError> {
        let var = |name: &str| std::env::var(format!("{prefix}{name}"));
        // Обратная совместимость: PLANNER_LLM_* (если prefix == "PLANNER_").
        let legacy = |name: &str| std::env::var(format!("PLANNER_LLM_{name}"));

        // Причина: у VarError ровно два варианта, а для отсутствующей
        // переменной исходный текст не добавляет ничего к явному сообщению.
        // ast-grep-ignore: required-error-context
        let provider = var("PROVIDER")
            .or_else(|_| legacy("PROVIDER"))
            .map_err(|_| LlmError::Config(format!("{prefix}PROVIDER required")))?;
        let api_key = var("API_KEY").or_else(|_| legacy("API_KEY")).ok();
        if provider != "mock" && provider != "openai-compatible" && api_key.is_none() {
            return Err(LlmError::Config(
                "API key required for this provider".into(),
            ));
        }
        let model = var("MODEL")
            .or_else(|_| legacy("MODEL"))
            .unwrap_or_else(|_| "mock".into());
        let base_url = var("BASE_URL").or_else(|_| legacy("BASE_URL")).ok();
        if provider == "openai-compatible" && base_url.is_none() {
            return Err(LlmError::Config(
                "BASE_URL required for openai-compatible".into(),
            ));
        }
        let max_retries = var("MAX_RETRIES")
            .or_else(|_| std::env::var("PLANNER_MAX_RETRIES"))
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(2);
        let max_tokens = var("MAX_TOKENS")
            .or_else(|_| std::env::var("PLANNER_BUDGET_TOKENS"))
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(4096);
        let mock_file = var("MOCK_RESPONSE_FILE")
            .or_else(|_| legacy("MOCK_RESPONSE_FILE"))
            .ok();
        let timeout_sec = var("TIMEOUT_SEC")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(120);
        Ok(Self {
            provider,
            api_key,
            model,
            base_url,
            max_retries,
            max_tokens,
            mock_file,
            timeout_sec,
        })
    }

    /// Совместимость: читает `LLM_*`, при отсутствии — `PLANNER_LLM_*`.
    pub fn from_env() -> Result<Self, LlmError> {
        Self::from_env_prefixed("LLM_")
    }
}

/// Запрос к LLM.
#[derive(Debug, Clone)]
pub struct LlmRequest {
    pub system: String,
    pub user: String,
    pub max_tokens: Option<u32>,
    pub temperature: Option<f32>,
    /// Модель для ЭТОГО запроса (Issue #7/#10). `None` → модель из конфига.
    ///
    /// Нужно, чтобы выбирать модель по измеренной стоимости успеха, не
    /// пересоздавая HTTP-клиент (в нём же ключ и base_url).
    pub model: Option<String>,
}

impl LlmRequest {
    /// Модель, которой реально уйдёт запрос: явная из запроса или из конфига.
    pub fn effective_model<'a>(&'a self, cfg_model: &'a str) -> &'a str {
        self.model.as_deref().unwrap_or(cfg_model)
    }
}

/// Ответ LLM.
#[derive(Debug, Clone)]
pub struct LlmResponse {
    pub text: String,
    pub tokens_in: u32,
    pub tokens_out: u32,
    pub model: String,
}

/// Трейт клиента — позволяет подменять реализацию в тестах.
pub trait LlmClient: Send + Sync {
    fn complete(&self, req: &LlmRequest) -> Result<LlmResponse, LlmError>;

    /// FIND-CODE-03: модель по умолчанию этого клиента — для аудита
    /// (`llm_calls.model`) при ошибке ДО ответа, когда реальное имя модели из
    /// ответа ещё неизвестно. Дефолт `"unknown"` сохраняет совместимость с
    /// тестовыми клиентами; HttpLlmClient отдаёт свою настроенную модель.
    fn default_model(&self) -> &str {
        "unknown"
    }
}

/// HTTP-клиент (blocking).
pub struct HttpLlmClient {
    cfg: LlmConfig,
    http: reqwest::blocking::Client,
}

#[derive(Serialize)]
struct ChatMessage<'a> {
    role: &'a str,
    content: &'a str,
}

#[derive(Serialize)]
struct OpenAiRequest<'a> {
    model: &'a str,
    messages: Vec<ChatMessage<'a>>,
    max_tokens: u32,
    temperature: f32,
}

#[derive(Deserialize)]
struct OpenAiChoice {
    message: OpenAiMessage,
}
#[derive(Deserialize)]
struct OpenAiMessage {
    content: String,
}
#[derive(Deserialize)]
struct OpenAiUsage {
    #[serde(default)]
    prompt_tokens: u32,
    #[serde(default)]
    completion_tokens: u32,
}
#[derive(Deserialize)]
struct OpenAiResponse {
    choices: Vec<OpenAiChoice>,
    #[serde(default)]
    usage: Option<OpenAiUsage>,
    #[serde(default)]
    model: Option<String>,
}

#[derive(Serialize)]
struct AnthropicRequest<'a> {
    model: &'a str,
    max_tokens: u32,
    system: &'a str,
    messages: Vec<ChatMessage<'a>>,
}
#[derive(Deserialize)]
struct AnthropicContent {
    text: String,
}
#[derive(Deserialize)]
struct AnthropicUsage {
    #[serde(default)]
    input_tokens: u32,
    #[serde(default)]
    output_tokens: u32,
}
#[derive(Deserialize)]
struct AnthropicResponse {
    content: Vec<AnthropicContent>,
    #[serde(default)]
    usage: Option<AnthropicUsage>,
    #[serde(default)]
    model: Option<String>,
}

impl HttpLlmClient {
    pub fn new(cfg: LlmConfig) -> Result<Self, LlmError> {
        let http = reqwest::blocking::Client::builder()
            .timeout(std::time::Duration::from_secs(cfg.timeout_sec))
            .build()
            .map_err(|e| LlmError::Transport(e.to_string()))?;
        Ok(Self { cfg, http })
    }

    pub fn config(&self) -> &LlmConfig {
        &self.cfg
    }

    fn dispatch(&self, req: &LlmRequest) -> Result<LlmResponse, LlmError> {
        let max_tokens = req.max_tokens.unwrap_or(self.cfg.max_tokens);
        match self.cfg.provider.as_str() {
            "mock" => self.mock_response(),
            "openai" => self.openai_chat(
                req,
                max_tokens,
                self.cfg
                    .base_url
                    .as_deref()
                    .unwrap_or("https://api.openai.com"),
            ),
            "openai-compatible" | "relayfast" => {
                let base = self
                    .cfg
                    .base_url
                    .as_deref()
                    .ok_or_else(|| LlmError::Config("base_url required".into()))?;
                self.openai_chat(req, max_tokens, base)
            }
            "anthropic" => self.anthropic_chat(req, max_tokens),
            other => Err(LlmError::Config(format!("unknown provider: {other}"))),
        }
    }

    fn mock_response(&self) -> Result<LlmResponse, LlmError> {
        let path = self
            .cfg
            .mock_file
            .as_deref()
            .ok_or_else(|| LlmError::Config("mock requires MOCK_RESPONSE_FILE".into()))?;
        // Волна 5.2: поддержка ПОСЛЕДОВАТЕЛЬНОСТИ ответов.
        // Если MOCK_RESPONSE_FILE — шаблон со звёздочкой (`dir/case*.json`),
        // мок выдаёт файлы по порядку сортировки при каждом вызове, сохраняя
        // счётчик в файле `dir/.mock_cursor`. Позволяет честно тестировать
        // retry (первый ответ невалиден, второй — валиден), чего одиночный
        // файл не давал (тест `planner_retries_on_invalid_json` был вакуумным).
        if let Some(dir) = path.strip_suffix("*") {
            return self.mock_sequence(dir);
        }
        let text = std::fs::read_to_string(path)
            .map_err(|e| LlmError::Transport(format!("mock file {path}: {e}")))?;
        Ok(LlmResponse {
            text,
            tokens_in: 0,
            tokens_out: 0,
            model: "mock".into(),
        })
    }

    /// Выдать следующий файл из последовательности `dir*` по счётчику.
    fn mock_sequence(&self, dir: &str) -> Result<LlmResponse, LlmError> {
        let dir = dir.trim_end_matches('/').to_string();
        let mut files: Vec<String> = std::fs::read_dir(&dir)
            .map_err(|e| LlmError::Transport(format!("mock seq dir {dir}: {e}")))?
            .filter_map(|e| e.ok())
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .filter(|n| n.ends_with(".json"))
            .collect();
        files.sort();
        if files.is_empty() {
            return Err(LlmError::Config(format!("mock seq dir {dir}: no *.json")));
        }
        let cursor_path = format!("{dir}/.mock_cursor");
        let n: usize = std::fs::read_to_string(&cursor_path)
            .ok()
            .and_then(|s| s.trim().parse().ok())
            .unwrap_or(0);
        let idx = n.min(files.len() - 1); // после конца — последний ответ
        std::fs::write(&cursor_path, (idx + 1).to_string())
            .map_err(|e| LlmError::Transport(format!("mock cursor {cursor_path}: {e}")))?;
        let text = std::fs::read_to_string(format!("{dir}/{}", files[idx]))
            .map_err(|e| LlmError::Transport(format!("mock seq file: {e}")))?;
        Ok(LlmResponse {
            text,
            tokens_in: 0,
            tokens_out: 0,
            model: "mock".into(),
        })
    }

    fn openai_chat(
        &self,
        req: &LlmRequest,
        max_tokens: u32,
        base: &str,
    ) -> Result<LlmResponse, LlmError> {
        let url = format!("{}/v1/chat/completions", base.trim_end_matches('/'));
        let body = OpenAiRequest {
            model: req.effective_model(&self.cfg.model),
            messages: vec![
                ChatMessage {
                    role: "system",
                    content: &req.system,
                },
                ChatMessage {
                    role: "user",
                    content: &req.user,
                },
            ],
            max_tokens,
            temperature: req.temperature.unwrap_or(0.2),
        };
        let mut r = self.http.post(&url).json(&body);
        if let Some(k) = &self.cfg.api_key {
            r = r.bearer_auth(k);
        }
        let resp = r.send().map_err(|e| LlmError::Transport(e.to_string()))?;
        let status = resp.status();
        let text = resp
            .text()
            .map_err(|e| LlmError::Transport(e.to_string()))?;
        if !status.is_success() {
            return Err(LlmError::Http {
                status: status.as_u16(),
                body: truncate(&text, 400),
            });
        }
        let parsed: OpenAiResponse = serde_json::from_str(&text)
            .map_err(|e| LlmError::InvalidJson(format!("{e}: {}", truncate(&text, 400))))?;
        let usage = parsed.usage.unwrap_or(OpenAiUsage {
            prompt_tokens: 0,
            completion_tokens: 0,
        });
        parsed
            .choices
            .into_iter()
            .next()
            .map(|c| LlmResponse {
                text: c.message.content,
                tokens_in: usage.prompt_tokens,
                tokens_out: usage.completion_tokens,
                model: parsed.model.unwrap_or_else(|| self.cfg.model.clone()),
            })
            .ok_or_else(|| LlmError::InvalidJson("empty choices".into()))
    }

    fn anthropic_chat(&self, req: &LlmRequest, max_tokens: u32) -> Result<LlmResponse, LlmError> {
        let base = self
            .cfg
            .base_url
            .as_deref()
            .unwrap_or("https://api.anthropic.com");
        let url = format!("{}/v1/messages", base.trim_end_matches('/'));
        let body = AnthropicRequest {
            model: req.effective_model(&self.cfg.model),
            max_tokens,
            system: &req.system,
            messages: vec![ChatMessage {
                role: "user",
                content: &req.user,
            }],
        };
        let key = self
            .cfg
            .api_key
            .as_deref()
            .ok_or_else(|| LlmError::Config("anthropic requires api key".into()))?;
        let resp = self
            .http
            .post(&url)
            .header("x-api-key", key)
            .header("anthropic-version", "2023-06-01")
            .json(&body)
            .send()
            .map_err(|e| LlmError::Transport(e.to_string()))?;
        let status = resp.status();
        let text = resp
            .text()
            .map_err(|e| LlmError::Transport(e.to_string()))?;
        if !status.is_success() {
            return Err(LlmError::Http {
                status: status.as_u16(),
                body: truncate(&text, 400),
            });
        }
        let parsed: AnthropicResponse = serde_json::from_str(&text)
            .map_err(|e| LlmError::InvalidJson(format!("{e}: {}", truncate(&text, 400))))?;
        let usage = parsed.usage.unwrap_or(AnthropicUsage {
            input_tokens: 0,
            output_tokens: 0,
        });
        parsed
            .content
            .into_iter()
            .next()
            .map(|c| LlmResponse {
                text: c.text,
                tokens_in: usage.input_tokens,
                tokens_out: usage.output_tokens,
                model: parsed.model.unwrap_or_else(|| self.cfg.model.clone()),
            })
            .ok_or_else(|| LlmError::InvalidJson("empty content".into()))
    }
}

impl LlmClient for HttpLlmClient {
    fn complete(&self, req: &LlmRequest) -> Result<LlmResponse, LlmError> {
        self.dispatch(req)
    }

    fn default_model(&self) -> &str {
        &self.cfg.model
    }
}

/// Фабрика из env.
pub fn from_env() -> Result<Box<dyn LlmClient>, LlmError> {
    let cfg = LlmConfig::from_env()?;
    Ok(Box::new(HttpLlmClient::new(cfg)?))
}

/// Фабрика из env с префиксом.
pub fn from_env_prefixed(prefix: &str) -> Result<Box<dyn LlmClient>, LlmError> {
    let cfg = LlmConfig::from_env_prefixed(prefix)?;
    Ok(Box::new(HttpLlmClient::new(cfg)?))
}

/// Обрезает строку до `n` БАЙТ, не разрывая символ UTF-8.
///
/// F18: тело ответа провайдера может быть на русском/китайском (провайдеры
/// отвечают на языке запроса). Старая реализация делала `&s[..n]` — срез по
/// байту; если `n` попадал в середину многобайтового символа, это **паника**
/// (`byte index N is not a char boundary`), а не обрезка. Паника в обработчике
/// ошибки прячет исходную ошибку провайдера и роняет воркер. Проверено на
/// `truncate("ыыыы", 3)` — паниковало до фикса.
fn truncate(s: &str, n: usize) -> String {
    if s.len() <= n {
        return s.to_string();
    }
    // Отступаем к ближайшей границе символа вниз.
    let mut end = n;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}…", &s[..end])
}

#[cfg(test)]
mod tests {
    use super::*;

    // F18: обрезка тела ответа не должна паниковать на многобайтовом UTF-8.
    // Провайдеры отвечают на языке запроса (русский/китайский); байтовый срез
    // `&s[..n]` попадал в середину символа и ронял воркер паникой вместо
    // обрезки. Проверено: до фикса `truncate("ыыыы", 3)` паниковало.
    #[test]
    fn truncate_is_utf8_safe() {
        // 3 байта — середина второго символа 'ы' (2 байта).
        let out = truncate("ыыыы", 3);
        assert!(out.ends_with('…'), "обрезанная строка помечена: {out:?}");
        // Обрезка не длиннее лимита + 3 байта самого многоточия ('…').
        assert!(
            out.len() <= 3 + '…'.len_utf8(),
            "результат не превышает границу: {out:?}"
        );
        // Китайский: 3 байта на символ.
        let out = truncate("中文字符", 4);
        assert!(out.ends_with('…'));
        // Строка короче лимита возвращается целиком, без маркера.
        assert_eq!(truncate("ок", 400), "ок");
        // ASCII на границе — без паники.
        assert_eq!(truncate("abcdef", 3), "abc…");
    }

    #[test]
    fn mock_returns_file_contents() {
        let dir = std::env::temp_dir();
        let p = dir.join(format!("swarm_llm_mock_{}.txt", std::process::id()));
        std::fs::write(&p, "hello-from-mock").unwrap();
        let cfg = LlmConfig {
            provider: "mock".into(),
            api_key: None,
            model: "mock".into(),
            base_url: None,
            max_retries: 0,
            max_tokens: 16,
            mock_file: Some(p.to_string_lossy().into_owned()),
            timeout_sec: 5,
        };
        let c = HttpLlmClient::new(cfg).unwrap();
        let r = c
            .complete(&LlmRequest {
                system: "s".into(),
                user: "u".into(),
                max_tokens: None,
                temperature: None,
                model: None,
            })
            .unwrap();
        assert_eq!(r.text, "hello-from-mock");
        let _ = std::fs::remove_file(&p);
    }

    #[test]
    fn mock_sequence_advances_per_call() {
        let dir = std::env::temp_dir().join(format!("swarm_llm_seq_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("001_invalid.json"), "not json").unwrap();
        std::fs::write(dir.join("002_valid.json"), "{\"ok\":true}").unwrap();
        let cfg = LlmConfig {
            provider: "mock".into(),
            api_key: None,
            model: "mock".into(),
            base_url: None,
            max_retries: 0,
            max_tokens: 16,
            mock_file: Some(format!("{}*", dir.display())),
            timeout_sec: 5,
        };
        let c = HttpLlmClient::new(cfg).unwrap();
        let req = LlmRequest {
            system: "s".into(),
            user: "u".into(),
            max_tokens: None,
            temperature: None,
            model: None,
        };
        let r1 = c.complete(&req).unwrap();
        assert_eq!(r1.text, "not json", "первый ответ — невалидный");
        let r2 = c.complete(&req).unwrap();
        assert_eq!(r2.text, "{\"ok\":true}", "второй ответ — валидный");
        let r3 = c.complete(&req).unwrap();
        assert_eq!(r3.text, "{\"ok\":true}", "после конца — последний");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn unknown_provider_errors() {
        let cfg = LlmConfig {
            provider: "nope".into(),
            api_key: Some("x".into()),
            model: "m".into(),
            base_url: None,
            max_retries: 0,
            max_tokens: 16,
            mock_file: None,
            timeout_sec: 5,
        };
        let c = HttpLlmClient::new(cfg).unwrap();
        let err = c.complete(&LlmRequest {
            system: "s".into(),
            user: "u".into(),
            max_tokens: None,
            temperature: None,
            model: None,
        });
        assert!(matches!(err, Err(LlmError::Config(_))));
    }
}

