//! Интеграционные тесты Planner: реальный Postgres, mock LLM.
//!
//! Запуск: TEST_DATABASE_URL=postgres://swarm@127.0.0.1:55440/v0planner \
//!         cargo test -p swarm-planner --test planner_integration -- --test-threads=1

use std::path::PathBuf;
use swarm_core::SwarmDispatcher;
use swarm_planner::{LlmClient, LlmConfig, Planner, PlannerConfig};

fn dsn() -> String {
    std::env::var("TEST_DATABASE_URL")
        .unwrap_or_else(|_| "postgres://swarm@127.0.0.1:55440/v0planner".into())
}

fn fixture(name: &str) -> String {
    let mut p = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    p.push("tests/fixtures");
    p.push(name);
    p.to_string_lossy().into_owned()
}

fn mock_cfg(fixture_name: &str) -> LlmConfig {
    LlmConfig {
        provider: "mock".into(),
        api_key: None,
        model: "mock".into(),
        base_url: None,
        max_retries: 2,
        max_tokens: 4096,
        mock_file: Some(fixture(fixture_name)),
    }
}

fn planner(fixture_name: &str, max_tasks: u32) -> Planner {
    let cfg = PlannerConfig {
        limits: swarm_planner::Limits {
            max_tasks,
            max_depth: 5,
            max_children: 10,
        },
    };
    Planner::new(cfg, LlmClient::new(mock_cfg(fixture_name)).unwrap())
}

/// Отказаться опустошать БД, которая не выглядит тестовой (аудит: `TRUNCATE
/// ... CASCADE` не должен уметь снести рабочую базу).
fn assert_disposable_db(dsn: &str) {
    let name = db_name(dsn);
    assert!(
        name.starts_with("test_") || name.starts_with("v0") || name.starts_with("c2_"),
        "refusing to TRUNCATE non-disposable database {name:?} \
         (allowed prefixes: test_, v0, c2_)"
    );
}

/// Имя БД из DSN: key=value (`dbname=...`) или URI (`postgres://.../db`).
fn db_name(dsn: &str) -> String {
    if let Some(rest) = dsn
        .strip_prefix("postgres://")
        .or_else(|| dsn.strip_prefix("postgresql://"))
    {
        let after_host = rest.split('/').nth(1).unwrap_or("");
        return after_host.split('?').next().unwrap_or("").to_string();
    }
    dsn.split_whitespace()
        .find_map(|p| p.strip_prefix("dbname="))
        .unwrap_or("")
        .to_string()
}

/// Очистка таблиц прямым SQL (тест-пользователь swarm — суперпользователь).
fn clear() {
    let dsn = dsn();
    assert_disposable_db(&dsn);
    let mut client = postgres::Client::connect(&dsn, postgres::NoTls).expect("raw connect");
    client
        .batch_execute("truncate events, reviews, task_deps, artifacts, tasks, workers cascade")
        .expect("truncate");
}

fn raw() -> postgres::Client {
    postgres::Client::connect(&dsn(), postgres::NoTls).expect("raw connect")
}

fn admin() -> SwarmDispatcher {
    clear();
    SwarmDispatcher::connect(&dsn()).expect("connect")
}

// 1. Planner создаёт 3 задачи, 2 зависимости.
#[test]
fn planner_creates_graph() {
    let mut d = admin();
    let p = planner("planner_ok.json", 50);
    let out = p.plan(&mut d, "задача-1").unwrap();
    assert!(!out.already_existed);
    assert_eq!(out.tasks_created, 3);
    assert_eq!(out.ready_to_execute, 1, "только корень должен быть ready");
    let rows = d.list_task_status(100).unwrap();
    assert_eq!(rows.iter().filter(|r| r.root_id == out.root_id).count(), 3);
}

// 2. Второй запуск с тем же текстом не создаёт дублей.
#[test]
fn planner_idempotent_same_text() {
    let mut d = admin();
    let p = planner("planner_ok.json", 50);
    let a = p.plan(&mut d, "задача-2").unwrap();
    assert_eq!(a.tasks_created, 3);
    let b = p.plan(&mut d, "задача-2").unwrap();
    assert!(b.already_existed, "второй запуск должен быть пропущен");
    assert_eq!(b.tasks_created, 0);
    assert_eq!(a.root_id, b.root_id);
    let rows = d.list_task_status(100).unwrap();
    assert_eq!(rows.iter().filter(|r| r.root_id == a.root_id).count(), 3);
}

// 3. Другой текст → другой граф.
#[test]
fn planner_idempotent_different_text() {
    let mut d = admin();
    let p = planner("planner_ok.json", 50);
    let a = p.plan(&mut d, "задача-3a").unwrap();
    let b = p.plan(&mut d, "задача-3b").unwrap();
    assert_ne!(a.root_id, b.root_id);
    assert_eq!(b.tasks_created, 3);
    let rows = d.list_task_status(100).unwrap();
    assert_eq!(rows.iter().filter(|r| r.root_id == a.root_id).count(), 3);
    assert_eq!(rows.iter().filter(|r| r.root_id == b.root_id).count(), 3);
}

// 4. Атомарность графа: граф проходит локальную валидацию, но падает на SQL
//    уже ПОСЛЕ вставки задач (дубль зависимости → PK violation на add_dep).
//    Проверяем через Planner::plan — то есть тем же путём, что и продакшн,
//    чтобы мутация M3 (with_transaction → последовательные add_task) ловилась.
#[test]
fn planner_atomic_on_sql_error() {
    let mut d = admin();
    let p = planner("planner_dup_dep.json", 50);
    let res = p.plan(&mut d, "задача-4");
    assert!(res.is_err(), "дубль зависимости должен уронить SQL-вставку");

    // Транзакция должна откатить ВСЕ вставленные задачи: в БД пусто.
    let rows = d.list_task_status(100).unwrap();
    assert!(
        rows.is_empty(),
        "транзакция должна была откатить весь граф, осталось задач: {}",
        rows.len()
    );
}

// 4b. Контроль атомарности на уровне dispatcher (как было в исходном тесте):
//     цикл зависимости рушит транзакцию, частичных вставок нет.
#[test]
fn dispatcher_transaction_rolls_back_on_cycle() {
    use serde_json::json;
    use swarm_core::{Budget, Needs, TaskContract};
    let mut d = admin();

    let root = uuid::Uuid::new_v4();
    let a = uuid::Uuid::new_v4();
    let b = uuid::Uuid::new_v4();
    let c = TaskContract {
        kind: "t".into(),
        description: None,
        checks: vec![json!({"type": "cmd", "run": "true"})],
        needs: Needs::default(),
        budget: Budget::default(),
    };

    let res: Result<(), swarm_core::DispatcherError> = d.with_transaction(|tx| {
        tx.add_task(root, &c, Some(root), 1000, 0)?;
        tx.add_task(a, &c, Some(root), 1000, 0)?;
        tx.add_task(b, &c, Some(root), 1000, 0)?;
        tx.add_dep(b, a)?;
        // цикл: a зависит от b, b зависит от a → GR001, транзакция рушится
        tx.add_dep(a, b)?;
        Ok(())
    });
    assert!(res.is_err(), "цикл должен откатить транзакцию");

    let rows = d.list_task_status(100).unwrap();
    assert!(
        rows.iter().all(|r| r.root_id != root),
        "транзакция должна была откатить все 3 задачи, осталось: {}",
        rows.len()
    );
}

// 5. Лимит max_tasks: LLM вернул 2 задачи при лимите 1 → отвергается.
#[test]
fn planner_respects_max_tasks() {
    let mut d = admin();
    let p = planner("planner_too_many.json", 1);
    let err = p.plan(&mut d, "задача-5");
    assert!(err.is_err(), "граф > max_tasks должен быть отвергнут");
    let rows = d.list_task_status(100).unwrap();
    assert!(rows.is_empty(), "при отказе валидации БД должна быть пуста");
}

// 6. Retry-путь: валидный ответ проходит; проверяем, что retry не мешает
//    (полноценный retry на битом JSON — в unit-тестах parse/validate).
#[test]
fn planner_retries_on_invalid_json() {
    // Волна 5.2: тест был ВАКУУМНЫМ — использовал planner_ok.json (валидный),
    // т.е. retry не срабатывал вообще. Теперь мок выдаёт ПОСЛЕДОВАТЕЛЬНОСТЬ:
    // 001_broken.json (невалидный) -> 002_ok.json (валидный). Планировщик обязан
    // пережить первый отказ и вернуть валидный граф со ВТОРОЙ попытки.
    let mut d = admin();
    let seq_dir = {
        let mut p = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
        p.push("tests/fixtures/retry_seq");
        p
    };
    // Чистим курсор мока, чтобы последовательность начиналась с 001_broken.
    let _ = std::fs::remove_file(seq_dir.join(".mock_cursor"));
    let cfg = PlannerConfig {
        limits: swarm_planner::Limits {
            max_tasks: 50,
            max_depth: 5,
            max_children: 10,
        },
    };
    let mut llm_cfg = mock_cfg("planner_ok.json");
    llm_cfg.max_retries = 2;
    llm_cfg.mock_file = Some(format!("{}*", seq_dir.display()));
    let p = Planner::new(cfg, LlmClient::new(llm_cfg).unwrap());
    let out = p.plan(&mut d, "задача-6").unwrap();
    assert_eq!(
        out.tasks_created, 3,
        "должен восстановиться со второй попытки"
    );
    // Курсор продвинулся => был >1 вызов (иначе retry не проверялся).
    let cursor: u32 = std::fs::read_to_string(seq_dir.join(".mock_cursor"))
        .unwrap()
        .trim()
        .parse()
        .unwrap();
    assert!(cursor >= 2, "ожидалось >=2 вызова LLM, было {cursor}");
}

// 7. e2e: Planner → worker выполняет → review.
#[test]
fn e2e_planner_to_review() {
    let mut d = admin();
    let p = planner("planner_ok.json", 50);
    let out = p.plan(&mut d, "задача-7").unwrap();
    assert_eq!(out.ready_to_execute, 1);

    d.register_worker("w1", &serde_json::json!({"ram_gb": 16}), &[])
        .unwrap();
    let lease = d
        .claim("w1", 60)
        .unwrap()
        .expect("корень должен быть выдан");
    d.save_artifact(&lease, "sha256:root", "/p", None, None)
        .unwrap();
    let state = d.complete(&lease, "sha256:root", 1).unwrap();
    assert_eq!(state, "review");

    let st = d
        .submit_review(
            out.root_id,
            "sha256:root",
            "reviewer",
            swarm_core::Verdict::Approved,
            &serde_json::json!([{"type": "cmd", "run": "true", "status": "pass", "exit_code": 0}]),
        )
        .unwrap();
    assert_eq!(st, "done");
    assert!(d.verify_chain(out.root_id).unwrap());
}

// 9. §6.4 (v0.3.1): description доезжает до БД — у корня (текст задачи)
//    и у подзадач (из ответа LLM).
#[test]
fn planner_description_reaches_db() {
    let mut d = admin();
    let p = planner("planner_ok.json", 50);
    let text = "рефакторинг модуля auth";
    let out = p.plan(&mut d, text).unwrap();

    let mut c = raw();
    let root_desc: Option<String> = c
        .query_one(
            "select contract->>'description' from tasks where id = $1",
            &[&out.root_id],
        )
        .unwrap()
        .get(0);
    assert_eq!(
        root_desc.as_deref(),
        Some(text),
        "корень должен нести текст задачи"
    );

    // подзадачи — со своими description из ответа LLM
    let subs: Vec<Option<String>> = c
        .query(
            "select contract->>'description' from tasks \
             where root_id = $1 and id <> $1 order by id",
            &[&out.root_id],
        )
        .unwrap()
        .iter()
        .map(|r| r.get(0))
        .collect();
    assert_eq!(subs.len(), 2, "в фикстуре 2 подзадачи");
    for s in subs {
        assert!(s.is_some(), "у каждой подзадачи должен быть description");
        assert!(!s.unwrap().is_empty());
    }
}

[package]
name = "swarm-reviewer"
version.workspace = true
edition.workspace = true

[dependencies]
swarm-core = { path = "../swarm-core" }
serde_json = { workspace = true }
tracing = { workspace = true }
tracing-subscriber = { workspace = true }
ctrlc = "3.4"

//! Ревьюер: независимая приёмка результата исполнителя (Issue #26).
//!
//! В прод-контуре не было компонента, закрывающего `review -> done`; задачи
//! копились в `review`, а зависимые `pending` не промоутились.
//!
//! Ревьюер НЕ выдумывает успех: он читает артефакт исполнителя и проверяет
//! его содержимое. Артефакт-заглушка (`{"error": ...}`), пустой или слишком
//! короткий получает `changes_requested` (движок уводит на доработку).
//!
//! Говорит с движком только публичными функциями: `review_candidates(n)` и
//! `submit_review(...)` — роль `swarm_reviewer` (least privilege, без прямого
//! SELECT на `tasks`/`artifacts`).
//!
//! Env:
//! - `DATABASE_URL` (обязательно) — DSN роли `swarm_reviewer`
//! - `REVIEWER_ID` (по умолчанию `agent_reviewer`) — должен отличаться от
//!   автора артефакта, иначе `submit_review` вернёт RV002 self_review
//! - `ARTIFACTS_DIR` (по умолчанию /var/swarm/artifacts) — точка монтирования
//!   общего volume артефактов
//! - `REVIEW_MIN_BYTES` (по умолчанию 80) — минимальный «полезный» размер
//! - `REVIEW_POLL_SEC` (по умолчанию 2.0) — период опроса кандидатов

use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;

use serde_json::{json, Value};
use swarm_core::{DispatcherError, SwarmDispatcher, Verdict};
use tracing::{error, info, warn};
use tracing_subscriber::EnvFilter;

const DEFAULT_ARTIFACTS_DIR: &str = "/var/swarm/artifacts";

struct ReviewerConfig {
    dsn: String,
    reviewer_id: String,
    artifacts_dir: PathBuf,
    min_bytes: usize,
    poll_sec: f64,
}

fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::from_default_env().add_directive(
                "swarm_reviewer=info"
                    .parse()
                    .expect("static directive is valid"),
            ),
        )
        .json()
        .init();

    let cfg = ReviewerConfig {
        dsn: std::env::var("DATABASE_URL").expect("DATABASE_URL must be set"),
        reviewer_id: std::env::var("REVIEWER_ID").unwrap_or_else(|_| "agent_reviewer".into()),
        artifacts_dir: PathBuf::from(
            std::env::var("ARTIFACTS_DIR").unwrap_or_else(|_| DEFAULT_ARTIFACTS_DIR.into()),
        ),
        min_bytes: std::env::var("REVIEW_MIN_BYTES")
            .ok()
            .and_then(|s| s.parse().ok())
            .unwrap_or(80),
        poll_sec: std::env::var("REVIEW_POLL_SEC")
            .ok()
            .and_then(|s| s.parse().ok())
            .unwrap_or(2.0),
    };

    let shutdown = Arc::new(AtomicBool::new(false));
    let s = shutdown.clone();
    ctrlc::set_handler(move || {
        info!("received shutdown signal, finishing current iteration");
        s.store(true, Ordering::SeqCst);
    })
    .expect("install signal handler");

    info!(
        reviewer_id = %cfg.reviewer_id,
        artifacts_dir = %cfg.artifacts_dir.display(),
        "reviewer starting"
    );

    let mut d = match SwarmDispatcher::connect(&cfg.dsn) {
        Ok(d) => d,
        Err(e) => {
            error!(error = %e, "connect failed");
            std::process::exit(2);
        }
    };

    let poll = Duration::from_secs_f64(cfg.poll_sec.max(0.2));
    while !shutdown.load(Ordering::SeqCst) {
        match review_once(&mut d, &cfg) {
            Ok(n) => {
                if n > 0 {
                    info!(reviewed = n, "iteration complete");
                }
            }
            Err(e) => warn!(error = %e, "iteration failed"),
        }
        // Прерываемый сон: сигнал останавливает без ожидания полного периода.
        let deadline = std::time::Instant::now() + poll;
        while std::time::Instant::now() < deadline {
            if shutdown.load(Ordering::SeqCst) {
                break;
            }
            thread::sleep(Duration::from_millis(100));
        }
    }
    info!("reviewer stopped");
}

/// Один проход: забрать кандидатов и вынести вердикт каждому.
/// Возвращает число обработанных кандидатов.
fn review_once(d: &mut SwarmDispatcher, cfg: &ReviewerConfig) -> Result<usize, DispatcherError> {
    let candidates = d.review_candidates(10)?;
    let mut done = 0usize;
    for cand in candidates {
        let Some(ref_) = cand.result_ref.clone() else {
            continue;
        };
        let text = cand
            .storage_path
            .as_deref()
            .and_then(|sp| read_artifact(sp, &cfg.artifacts_dir));
        let (verdict, reasons) = verify(&cand.contract, text.as_deref(), cfg.min_bytes);
        let checks = checks_for(&cand.contract, &ref_, verdict == Verdict::Approved);
        match d.submit_review(cand.id, &ref_, &cfg.reviewer_id, verdict, &checks) {
            Ok(state) => {
                let note = if verdict == Verdict::Approved {
                    String::new()
                } else {
                    format!(" ({})", reasons.join("; "))
                };
                info!(
                    task = %cand.id,
                    verdict = verdict.as_str(),
                    state = %state,
                    note = %note,
                    "reviewed"
                );
                done += 1;
            }
            // Гонка: пока читали артефакт, задачу сняли/переоткрыли — не наша ошибка.
            Err(e) => warn!(task = %cand.id, error = %e, "submit_review failed"),
        }
    }
    Ok(done)
}

/// Прочитать текст артефакта по `storage_path`.
///
/// `storage_path` бывает двух видов (см. `swarm-worker::worker::local_storage_uri`):
///   * `volume://<name>/<relpath>` — разрешаем относительно `ARTIFACTS_DIR`;
///   * абсолютный путь (локальный режим) — читаем как есть.
/// Фолбэк по basename покрывает случай, когда volume смонтирован в другую точку.
fn read_artifact(storage_path: &str, artifacts_dir: &Path) -> Option<String> {
    let candidates = artifact_candidates(storage_path, artifacts_dir);
    for p in candidates {
        if let Ok(bytes) = std::fs::read(&p) {
            return Some(String::from_utf8_lossy(&bytes).into_owned());
        }
    }
    None
}

fn artifact_candidates(storage_path: &str, artifacts_dir: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Some(rest) = storage_path.strip_prefix("volume://") {
        // rest = "<name>/<relpath>"
        if let Some((_vol, rel)) = rest.split_once('/') {
            out.push(artifacts_dir.join(rel));
        }
    } else {
        out.push(PathBuf::from(storage_path));
    }
    if let Some(base) = Path::new(storage_path).file_name() {
        out.push(artifacts_dir.join(base));
    }
    out
}

/// Артефакт-отчёт воркера о невозможности выполнить контракт
/// (`{"error": ...}` — маркер отказа, см. `fail_artifact` в воркере).
fn looks_like_error(text: &str) -> bool {
    let head = text.trim();
    if !head.starts_with('{') {
        return false;
    }
    match serde_json::from_str::<Value>(head) {
        Ok(Value::Object(map)) => map.contains_key("error"),
        _ => false,
    }
}

/// Реальная проверка артефакта. Возвращает `(вердикт, причины)`.
fn verify(contract: &Value, text: Option<&str>, min_bytes: usize) -> (Verdict, Vec<String>) {
    let Some(text) = text else {
        return (Verdict::ChangesRequested, vec!["артефакт не найден".into()]);
    };
    let body = text.trim();
    if body.is_empty() {
        return (Verdict::ChangesRequested, vec!["артефакт пуст".into()]);
    }
    if looks_like_error(body) {
        let detail = serde_json::from_str::<Value>(body)
            .ok()
            .and_then(|v| v.get("error").and_then(|e| e.as_str()).map(String::from))
            .unwrap_or_default();
        return (
            Verdict::ChangesRequested,
            vec![format!(
                "исполнитель вернул ошибку: {}",
                truncate(&detail, 120)
            )],
        );
    }
    let _ = contract;
    if body.len() < min_bytes {
        return (
            Verdict::ChangesRequested,
            vec![format!(
                "слишком короткий результат ({} символов)",
                body.len()
            )],
        );
    }
    (Verdict::Approved, Vec::new())
}

/// Набор проверок по требованиям контракта с фактическим статусом.
///
/// Ключ проверки = `coalesce(id, type || '|' || run)` — ровно так его считает
/// строгий review-gate в `submit_review` (RV003). Один элемент отчёта на
/// каждое требование контракта, иначе гейт отклонит «зелёный» набор.
fn checks_for(contract: &Value, artifact_ref: &str, ok: bool) -> Value {
    let reqs = contract
        .get("checks")
        .and_then(|c| c.as_array())
        .cloned()
        .unwrap_or_default();
    let status = if ok { "pass" } else { "fail" };
    let mut checks = Vec::with_capacity(reqs.len());
    for c in reqs {
        let ctype = c.get("type").and_then(|v| v.as_str()).unwrap_or("check");
        let run = c.get("run").and_then(|v| v.as_str()).unwrap_or("");
        let id = c
            .get("id")
            .and_then(|v| v.as_str())
            .map(String::from)
            .unwrap_or_else(|| format!("{ctype}|{run}"));
        checks.push(json!({
            "id": id,
            "type": ctype,
            "run": run,
            "status": status,
            "artifact_ref": artifact_ref,
        }));
    }
    Value::Array(checks)
}

fn truncate(s: &str, n: usize) -> String {
    if s.chars().count() <= n {
        return s.to_string();
    }
    s.chars().take(n).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn contract_with(checks: Value) -> Value {
        json!({"kind": "test", "checks": checks})
    }

    #[test]
    fn missing_artifact_is_changes_requested() {
        let (v, r) = verify(&contract_with(json!([])), None, 10);
        assert_eq!(v, Verdict::ChangesRequested);
        assert!(r[0].contains("не найден"));
    }

    #[test]
    fn empty_and_whitespace_are_changes_requested() {
        let c = contract_with(json!([]));
        assert_eq!(verify(&c, Some(""), 10).0, Verdict::ChangesRequested);
        assert_eq!(verify(&c, Some("  \n\t "), 10).0, Verdict::ChangesRequested);
    }

    #[test]
    fn error_marker_is_changes_requested() {
        let c = contract_with(json!([]));
        let body = r#"{"error":"empty_response: LLM вернул пустой ответ","task_id":"x","epoch":1}"#;
        let (v, r) = verify(&c, Some(body), 1);
        assert_eq!(v, Verdict::ChangesRequested);
        assert!(r[0].contains("ошибку"));
    }

    #[test]
    fn short_result_is_changes_requested() {
        let c = contract_with(json!([]));
        let (v, r) = verify(&c, Some("ok"), 80);
        assert_eq!(v, Verdict::ChangesRequested);
        assert!(r[0].contains("короткий"));
    }

    #[test]
    fn useful_result_is_approved() {
        let c = contract_with(json!([]));
        let body = "A".repeat(200);
        assert_eq!(verify(&c, Some(&body), 80).0, Verdict::Approved);
    }

    #[test]
    fn checks_mirror_contract_keys() {
        let c = contract_with(json!([
            {"type": "cmd", "run": "cargo test"},
            {"id": "lint", "type": "cmd", "run": "cargo clippy"}
        ]));
        let checks = checks_for(&c, "sha256:abc", true);
        let arr = checks.as_array().unwrap();
        assert_eq!(arr.len(), 2);
        assert_eq!(arr[0]["id"], "cmd|cargo test");
        assert_eq!(arr[0]["status"], "pass");
        assert_eq!(arr[1]["id"], "lint");
        assert_eq!(arr[1]["artifact_ref"], "sha256:abc");
        // Провал: тот же набор ключей, но status=fail — гейт не пропустит approved.
        let bad = checks_for(&c, "sha256:abc", false);
        assert!(bad
            .as_array()
            .unwrap()
            .iter()
            .all(|c| c["status"] == "fail"));
    }

    #[test]
    fn volume_uri_resolves_under_mount() {
        let cands = artifact_candidates(
            "volume://swarm-artifacts/deadbeef.txt",
            Path::new("/var/swarm/artifacts"),
        );
        assert_eq!(cands[0], PathBuf::from("/var/swarm/artifacts/deadbeef.txt"));
    }

    #[test]
    fn absolute_path_used_as_is() {
        let cands = artifact_candidates("/tmp/art.txt", Path::new("/var/swarm/artifacts"));
        assert_eq!(cands[0], PathBuf::from("/tmp/art.txt"));
    }
}

[package]
name = "swarm-watchdog"
version.workspace = true
edition.workspace = true

[dependencies]
swarm-core = { path = "../swarm-core" }
tracing = { workspace = true }
tracing-subscriber = { workspace = true }
ctrlc = "3.4"

//! Сторож: раз в N секунд вызывает `reclaim_expired` и `promote_ready`.
//!
//! Отдельный процесс. Падение воркера не останавливает восстановление аренд.
//! Несколько копий безопасны: обе функции работают через FOR UPDATE SKIP LOCKED.

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;

use swarm_core::{DispatcherError, SwarmDispatcher};
use tracing::{debug, error, info};
use tracing_subscriber::EnvFilter;

const DEFAULT_INTERVAL_SEC: u64 = 30;
const MAX_BACKOFF_SEC: u64 = 30;

fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::from_default_env().add_directive(
                "swarm_watchdog=info"
                    .parse()
                    .expect("static directive is valid"),
            ),
        )
        .json()
        .init();

    let dsn = std::env::var("DATABASE_URL").expect("DATABASE_URL must be set");
    let interval = std::env::var("WATCHDOG_INTERVAL")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(DEFAULT_INTERVAL_SEC);

    let shutdown = Arc::new(AtomicBool::new(false));
    let shutdown_handler = shutdown.clone();
    ctrlc::set_handler(move || {
        info!("received shutdown signal, finishing current iteration");
        shutdown_handler.store(true, Ordering::SeqCst);
    })
    .expect("install signal handler");

    info!(interval_sec = interval, "watchdog starting");

    let mut backoff = 1u64;
    while !shutdown.load(Ordering::SeqCst) {
        match run_iteration(&dsn) {
            Ok((reclaimed, promoted)) => {
                if reclaimed > 0 || promoted > 0 {
                    info!(reclaimed, promoted, "iteration complete");
                } else {
                    debug!("no changes");
                }
                backoff = 1;
                sleep_until(&shutdown, interval);
            }
            Err(e) => {
                error!(error = %e, backoff_sec = backoff, "iteration failed");
                sleep_until(&shutdown, backoff);
                backoff = (backoff * 2).min(MAX_BACKOFF_SEC);
            }
        }
    }
    info!("watchdog stopped");
}

/// Одна итерация: reclaim + promote. Открывает новое соединение каждый раз —
/// так падение не оставляет «залипшее» подключение.
fn run_iteration(dsn: &str) -> Result<(i32, i32), DispatcherError> {
    let mut d = SwarmDispatcher::connect(dsn)?;
    let reclaimed = d.reclaim_expired()?;
    let promoted = d.promote_ready()?;
    Ok((reclaimed, promoted))
}

/// Спит с проверкой флага shutdown. Возвращается сразу после сигнала.
fn sleep_until(shutdown: &AtomicBool, secs: u64) {
    let step = Duration::from_millis(500);
    let total = Duration::from_secs(secs);
    let start = std::time::Instant::now();
    while start.elapsed() < total {
        if shutdown.load(Ordering::SeqCst) {
            return;
        }
        thread::sleep(step);
    }
}

//! Интеграционные тесты watchdog (Волна 5.2).
//!
//! Дефект: `swarm-watchdog` (84 строки) не имел ни одного теста, хотя это
//! отдельный процесс, который восстанавливает истёкшие аренды — критичный
//! путь «воркер упал -> задача не залипает».
//!
//! Проверяем поведение СОБРАННОГО бинаря как процесса:
//!  1) без DATABASE_URL — падает ненулевым кодом (fail-closed конфиг);
//!  2) с живой БД — стартует, делает итерации и корректно завершается по SIGINT
//!     (graceful shutdown через ctrlc).
//!
//! Требует TEST_DATABASE_URL. Без него второй тест выходит с явным FAIL
//! (FIND-08: не молчаливый пропуск).

use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

fn watchdog_bin() -> String {
    env!("CARGO_BIN_EXE_swarm-watchdog").to_string()
}

/// Без DATABASE_URL watchdog обязан упасть ненулевым кодом.
#[test]
fn watchdog_requires_database_url() {
    let out = Command::new(watchdog_bin())
        .env_remove("DATABASE_URL")
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .output()
        .expect("spawn watchdog");
    assert!(
        !out.status.success(),
        "без DATABASE_URL watchdog должен завершиться ненулевым кодом"
    );
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(
        err.contains("DATABASE_URL"),
        "сообщение должно упоминать DATABASE_URL, получено: {err}"
    );
}

/// С живой БД: стартует, крутит итерации и завершается по SIGINT с кодом 0.
#[test]
fn watchdog_starts_and_stops_gracefully_on_sigint() {
    let dsn = std::env::var("TEST_DATABASE_URL").unwrap_or_else(|_| {
        panic!(
            "BLOCKED/FAIL: TEST_DATABASE_URL не задан; watchdog-тест требует живую \
             тестовую БД (prefix test_/v0/c2_)"
        )
    });

    let mut child = Command::new(watchdog_bin())
        .env("DATABASE_URL", dsn)
        .env("WATCHDOG_INTERVAL", "1")
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("spawn watchdog");

    // Дать процессу стартовать и сделать хотя бы одну итерацию.
    std::thread::sleep(Duration::from_secs(2));

    // SIGINT -> graceful shutdown.
    let pid = child.id() as i32;
    unsafe {
        libc_kill(pid, 2); // SIGINT
    }

    // Ожидаем завершения с таймаутом.
    let deadline = Instant::now() + Duration::from_secs(10);
    loop {
        match child.try_wait().expect("try_wait") {
            Some(status) => {
                assert!(
                    status.success(),
                    "watchdog должен завершиться с кодом 0 по SIGINT, получено: {status:?}"
                );
                return;
            }
            None if Instant::now() > deadline => {
                let _ = child.kill();
                panic!("watchdog не завершился в течение 10s после SIGINT");
            }
            None => std::thread::sleep(Duration::from_millis(200)),
        }
    }
}

// Обёртка над libc::kill без дополнительной зависимости: используем команду
// `kill` из coreutils (доступна везде, где есть bash).
unsafe fn libc_kill(pid: i32, sig: i32) {
    let mut cmd = Command::new("kill");
    cmd.arg(format!("-{sig}")).arg(pid.to_string());
    let _ = cmd.status();
}

