//! Демонстрация Agent Loop с реальным LLM и реальным Docker (ТЗ v0.4 §8.3, §11.9).
//!
//! Прогоняет полный путь: task → claim → Agent Loop (LLM делает ≥2 tool calls
//! в sandbox) → артефакт на диск → complete → review → done.
//!
//! Запуск:
//!   DATABASE_URL="host=127.0.0.1 port=55440 user=swarm password=pw dbname=v0sandbox" \
//!   LLM_PROVIDER=openai-compatible LLM_BASE_URL=https://relay.fast/api/v1 \
//!   LLM_API_KEY=... LLM_MODEL=... \
//!   ARTIFACTS_DIR=/tmp/demo_artifacts \
//!   cargo run -p swarm-worker --example agent_loop_demo --locked

use std::path::PathBuf;

use swarm_core::{SwarmDispatcher, TaskContract};
use swarm_llm::from_env as llm_from_env;
use swarm_worker::agent_loop::{self, AgentLoopConfig};
use swarm_worker::allowlist::Allowlist;
use swarm_worker::audit::{count_tool_calls, PgAuditSink};
use swarm_worker::sandbox::Sandbox;
use swarm_worker::WorkerError;

fn main() {
    let dsn = std::env::var("DATABASE_URL").expect("DATABASE_URL");
    let artifacts_dir = PathBuf::from(
        std::env::var("ARTIFACTS_DIR").unwrap_or_else(|_| "/tmp/demo_artifacts".into()),
    );
    std::fs::create_dir_all(&artifacts_dir).expect("artifacts dir");

    let mut d = SwarmDispatcher::connect(&dsn).expect("connect");
    let worker = "w1";
    d.register_worker(worker, &serde_json::json!({"ram_gb": 16}), &[])
        .expect("register");

    // 1. Задача: реальная мини-задача, решаемая shell-инструментами.
    let contract: TaskContract = serde_json::from_value(serde_json::json!({
        "kind": "code.generate",
        "description": "Создай библиотечный крейт demo (cargo init --lib --name demo), \
                        добавь в src/lib.rs функцию add(a,b), запусти cargo test и покажи результат.",
        "checks": [{"type": "cmd", "run": "true"}]
    }))
    .expect("contract");

    let task_id = uuid::Uuid::new_v4();
    d.with_transaction(|w| w.add_task(task_id, &contract, None, 1_000_000, 0))
        .expect("add_task");
    d.promote_ready().expect("promote");

    // 2. Аренда.
    let lease = d.claim(worker, 900).expect("claim").expect("lease");
    println!("lease: task={} epoch={}", lease.task_id, lease.epoch);

    // 3. Sandbox.
    let cfg = AgentLoopConfig {
        max_iterations: 12,
        max_tokens: 2048,
        ..Default::default()
    };
    let sb = Sandbox::start(&cfg.sandbox, &lease.task_id.to_string()[..12]).expect("sandbox start");
    println!("sandbox: {}", sb.name());

    // 4. Реальный LLM.
    let llm = llm_from_env().expect("llm from env");
    let mut sink =
        PgAuditSink::connect(&dsn, lease.task_id, worker, lease.epoch).expect("audit sink");

    let res = agent_loop::run(
        llm.as_ref(),
        &sb,
        &serde_json::to_value(&contract).unwrap(),
        &Allowlist::default(),
        &cfg,
        &mut sink,
    );

    let mut sb = sb;
    let _ = sb.stop();

    match res {
        Ok(r) => {
            println!("\n=== AGENT LOOP ===");
            println!("итераций: {}", r.iterations);
            println!("tool calls: {}", r.tool_calls);
            println!("финальный ответ:\n{}", r.final_text);

            let (reference, path, size) =
                swarm_worker::artifacts::write_artifact(&artifacts_dir, r.final_text.as_bytes())
                    .expect("write artifact");
            d.save_artifact(
                &lease,
                &reference,
                &path.to_string_lossy(),
                Some("text/plain"),
                Some(size as i64),
            )
            .expect("save_artifact");
            let st = d.complete(&lease, &reference, 0).expect("complete");
            println!("\nartifact: {reference} ({size} B) -> {path:?}");
            println!("state after complete: {st}");

            let n = count_tool_calls(&dsn, lease.task_id).unwrap_or(-1);
            println!("событий tool_call в журнале: {n}");
            println!(
                "verify_chain: {}",
                d.verify_chain(lease.task_id).unwrap_or(false)
            );

            assert!(
                r.tool_calls >= 2,
                "ожидалось ≥2 tool call, получено {}",
                r.tool_calls
            );
            println!("\nOK: agent loop выполнил ≥2 tool call с реальным LLM");
        }
        Err(e) => {
            eprintln!("AGENT LOOP FAILED: {e}");
            if let WorkerError::MaxIterations { max } = e {
                eprintln!("(лимит итераций {max} исчерпан)");
            }
            std::process::exit(1);
        }
    }
}

//! Agent Loop с tool calls (ТЗ v0.4 §1, §6).
//!
//! LLM получает контракт и описание, затем в цикле возвращает либо tool call
//! (`run_shell`, `read_file`, `write_file`), либо финальный ответ. Каждый tool
//! call проверяется allowlist'ом, исполняется в sandbox и логируется событием
//! `tool_call` (ТЗ §7).
//!
//! Только синхронно, без async.

use crate::allowlist::Allowlist;
use crate::error::{Result, WorkerError};
use crate::sandbox::{ExecOutput, Sandbox, SandboxConfig};
use serde_json::Value;
use swarm_llm::{LlmClient, LlmRequest};

/// Максимум итераций по умолчанию (ТЗ §6).
pub const DEFAULT_MAX_ITERATIONS: u32 = 20;

/// Конфигурация Agent Loop.
#[derive(Debug, Clone)]
pub struct AgentLoopConfig {
    pub max_iterations: u32,
    pub max_tokens: u32,
    pub sandbox: SandboxConfig,
}

impl Default for AgentLoopConfig {
    fn default() -> Self {
        Self {
            max_iterations: DEFAULT_MAX_ITERATIONS,
            max_tokens: 4096,
            // N4 (Волна 5.2): sandbox читается из окружения — лимиты (в т.ч.
            // pids_limit) можно поднять без пересборки, когда крупные сборки
            // упираются в дефолт 256 процессов.
            sandbox: SandboxConfig::from_env(),
        }
    }
}

/// Один шаг LLM.
#[derive(Debug, Clone, PartialEq)]
pub enum Step {
    Tool(ToolCall),
    /// Несколько последовательных вызовов из одного DSML-ответа.
    ToolCalls(Vec<ToolCall>),
    Done {
        result: String,
    },
}

/// Разобранный tool call.
#[derive(Debug, Clone, PartialEq)]
pub struct ToolCall {
    pub tool: String,
    pub args: Value,
}

impl ToolCall {
    /// Команда, которая уйдёт в sandbox (для `run_shell` / `read_file`).
    pub fn shell_command(&self) -> Option<String> {
        match self.tool.as_str() {
            "run_shell" => self
                .args
                .get("command")
                .and_then(|c| c.as_str())
                .map(str::to_string),
            "read_file" => self
                .args
                .get("path")
                .and_then(|p| p.as_str())
                .map(str::to_string),
            _ => None,
        }
    }
}

/// Аудит одного tool call (ТЗ §7 — только hash + размер, без полного вывода).
#[derive(Debug, Clone, Default)]
pub struct ToolAudit {
    pub tool: String,
    pub command: Option<String>,
    pub exit_code: Option<i32>,
    pub duration_ms: u128,
    pub output_sha256: String,
    pub output_bytes: usize,
    pub truncated: bool,
    pub rejected: bool,
    pub reason: Option<String>,
}

/// Приёмник аудит-событий. Отдельный трейт — чтобы loop не зависел от Postgres.
pub trait ToolAuditSink {
    fn record(&mut self, audit: &ToolAudit) -> Result<()>;
}

/// Ничего не пишет (тесты, запуск без аудита).
pub struct NoopSink;
impl ToolAuditSink for NoopSink {
    fn record(&mut self, _a: &ToolAudit) -> Result<()> {
        Ok(())
    }
}

/// Результат работы Agent Loop.
#[derive(Debug, Clone)]
pub struct AgentResult {
    pub final_text: String,
    pub iterations: u32,
    pub tool_calls: usize,
}

/// Разобрать JSON или DSML-ответ LLM в шаг Agent Loop.
pub fn parse_step(text: &str) -> Result<Step> {
    crate::parse_step::parse(text)
}

/// Прогнать Agent Loop до финального ответа.
///
/// `history` — накопленные результаты tool calls, передаются обратно в LLM.
pub fn run(
    llm: &dyn LlmClient,
    sandbox: &Sandbox,
    contract: &Value,
    allowlist: &Allowlist,
    cfg: &AgentLoopConfig,
    sink: &mut dyn ToolAuditSink,
) -> Result<AgentResult> {
    let mut history: Vec<String> = Vec::new();
    let mut tool_calls = 0usize;

    for iteration in 1..=cfg.max_iterations {
        let req = LlmRequest {
            system: crate::prompt::agent_system_prompt(allowlist),
            user: crate::prompt::agent_user_prompt(contract, &history),
            max_tokens: Some(cfg.max_tokens),
            temperature: None,
            model: None,
        };
        let resp = llm.complete(&req)?;
        let step = parse_step(&resp.text)?;

        match step {
            Step::Done { result } => {
                return Ok(AgentResult {
                    final_text: result,
                    iterations: iteration,
                    tool_calls,
                });
            }
            Step::Tool(tc) => {
                let rejected = run_tool_and_record(sandbox, allowlist, sink, &tc, &mut history)?;
                tool_calls += 1;
                if rejected {
                    history.push(
                        "Отклонённый tool call: исправь этот шаг; не повторяй запрещённую команду."
                            .into(),
                    );
                }
            }
            Step::ToolCalls(calls) => {
                for (index, tc) in calls.into_iter().enumerate() {
                    let rejected =
                        run_tool_and_record(sandbox, allowlist, sink, &tc, &mut history)?;
                    tool_calls += 1;
                    if rejected {
                        history.push(format!(
                            "Шаг {} batch отклонён политикой; остальные вызовы не выполнялись. Исправь этот шаг и продолжай отдельным вызовом.",
                            index + 1
                        ));
                        break;
                    }
                }
            }
        }
    }

    Err(WorkerError::MaxIterations {
        max: cfg.max_iterations,
    })
}

fn run_tool_and_record(
    sandbox: &Sandbox,
    allowlist: &Allowlist,
    sink: &mut dyn ToolAuditSink,
    tc: &ToolCall,
    history: &mut Vec<String>,
) -> Result<bool> {
    let (reply, audit) = execute_tool(sandbox, allowlist, tc)?;
    let rejected = audit.rejected;
    sink.record(&audit)?;
    history.push(format!(
        "tool={} args={} -> {}",
        tc.tool,
        serde_json::to_string(&tc.args).unwrap_or_default(),
        reply
    ));
    Ok(rejected)
}

/// Выполнить один tool call: allowlist → sandbox → результат для LLM.
fn execute_tool(
    sandbox: &Sandbox,
    allowlist: &Allowlist,
    tc: &ToolCall,
) -> Result<(String, ToolAudit)> {
    let mut audit = ToolAudit {
        tool: tc.tool.clone(),
        ..Default::default()
    };

    match tc.tool.as_str() {
        "run_shell" => {
            let cmd = tc
                .shell_command()
                .ok_or_else(|| WorkerError::InvalidToolCall("run_shell: нет command".into()))?;
            audit.command = Some(cmd.clone());

            if let Err(e) = allowlist.check(&cmd) {
                audit.rejected = true;
                audit.reason = Some(e.to_string());
                return Ok((format!("REJECTED: {e}"), audit));
            }

            let out = sandbox.exec(&cmd)?;
            fill_audit(&mut audit, &out);
            Ok((render_output(&out), audit))
        }
        "read_file" => {
            let path = tc
                .shell_command()
                .ok_or_else(|| WorkerError::InvalidToolCall("read_file: нет path".into()))?;
            audit.command = Some(format!("read_file {path}"));
            if let Err(e) = validate_workspace_path(&path) {
                audit.rejected = true;
                audit.reason = Some(e.to_string());
                return Ok((format!("REJECTED: {e}"), audit));
            }
            let out = sandbox.read_file(&path)?;
            fill_audit(&mut audit, &out);
            Ok((render_output(&out), audit))
        }
        "write_file" => {
            let path = tc
                .args
                .get("path")
                .and_then(|p| p.as_str())
                .ok_or_else(|| WorkerError::InvalidToolCall("write_file: нет path".into()))?;
            let content = tc
                .args
                .get("content")
                .and_then(|c| c.as_str())
                .unwrap_or("");
            // Путь проверяем тем же правилом, что и команды.
            if let Err(e) = allowlist.check(&format!("touch {path}")) {
                audit.rejected = true;
                audit.reason = Some(e.to_string());
                return Ok((format!("REJECTED: {e}"), audit));
            }
            let out = sandbox.write_file(path, content)?;
            fill_audit(&mut audit, &out);
            Ok((render_output(&out), audit))
        }
        other => Err(WorkerError::InvalidToolCall(format!(
            "неизвестный инструмент: {other}"
        ))),
    }
}

fn validate_workspace_path(path: &str) -> Result<()> {
    let p = std::path::Path::new(path);
    // P0-2: путь уходит в argv (`cat -- <path>`), поэтому shell его не
    // интерпретирует. Дополнительно отклоняем метасимволы и управляющие
    // символы — защита в глубину: путь не должен быть похож на команду
    // (`x; cmd`, `x && cmd`, backticks, `$(...)`, пайпы, редиректы).
    const FORBIDDEN: &[char] = &[';', '&', '|', '<', '>', '`', '$', '\\', '*', '?', '{', '}'];
    if path.is_empty()
        || path.contains('\0')
        || path.contains('\n')
        || path.contains('\r')
        || path.chars().any(|c| FORBIDDEN.contains(&c))
        || p.is_absolute()
        || p.components()
            .any(|c| matches!(c, std::path::Component::ParentDir))
    {
        return Err(WorkerError::InvalidToolCall(
            "read_file: path must stay inside the workspace".into(),
        ));
    }
    Ok(())
}

fn fill_audit(audit: &mut ToolAudit, out: &ExecOutput) {
    audit.exit_code = Some(out.exit_code);
    audit.duration_ms = out.duration_ms;
    audit.output_sha256 = out.output_sha256.clone();
    audit.output_bytes = out.output_bytes;
    audit.truncated = out.truncated;
}

fn render_output(out: &ExecOutput) -> String {
    format!(
        "exit_code={}\nstdout:\n{}\nstderr:\n{}",
        out.exit_code,
        out.stdout.trim_end(),
        out.stderr.trim_end()
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn parse_done() {
        let s = parse_step(r#"{"done": true, "result": "готово"}"#).unwrap();
        assert_eq!(
            s,
            Step::Done {
                result: "готово".into()
            }
        );
    }

    #[test]
    fn parse_artifact_alias() {
        let s = parse_step(r#"{"done": true, "artifact": "cargo test ok"}"#).unwrap();
        assert_eq!(
            s,
            Step::Done {
                result: "cargo test ok".into()
            }
        );
    }

    #[test]
    fn parse_tool_call() {
        let s = parse_step(r#"{"tool": "run_shell", "args": {"command": "cargo test"}}"#).unwrap();
        match s {
            Step::Tool(tc) => {
                assert_eq!(tc.tool, "run_shell");
                assert_eq!(tc.shell_command().unwrap(), "cargo test");
            }
            _ => panic!("ожидался Tool"),
        }
    }

    #[test]
    fn parse_tool_in_fenced_block() {
        let text =
            "Вот вызов:\n```json\n{\"tool\":\"read_file\",\"args\":{\"path\":\"Cargo.toml\"}}\n```";
        match parse_step(text).unwrap() {
            Step::Tool(tc) => assert_eq!(tc.shell_command().unwrap(), "Cargo.toml"),
            _ => panic!("ожидался Tool"),
        }
    }

    #[test]
    fn parse_rejects_malformed_quoted_dsml_parameter() {
        let text = r#"<｜｜DSML｜｜ invoke name="run_shell"><｜｜DSML｜｜ parameter name="command" string="true">"printf \q"</｜｜DSML｜｜ parameter></｜｜DSML｜｜ invoke>"#;
        assert!(matches!(
            parse_step(text),
            Err(WorkerError::InvalidToolCall(_))
        ));
    }

    #[test]
    fn parse_rejects_truncated_quoted_dsml_parameter() {
        let text = r#"<｜｜DSML｜｜ invoke name="run_shell"><｜｜DSML｜｜ parameter name="command" string="true">"printf hello</｜｜DSML｜｜ parameter></｜｜DSML｜｜ invoke>"#;
        assert!(matches!(
            parse_step(text),
            Err(WorkerError::InvalidToolCall(_))
        ));
    }

    #[test]
    fn parse_garbage_fails() {
        assert!(parse_step("просто текст без json").is_err());
        assert!(parse_step(r#"{"foo": 1}"#).is_err());
    }

    #[test]
    fn parse_handles_braces_inside_strings() {
        let s = parse_step(r#"{"done": true, "result": "if (x) { return 1; }"}"#).unwrap();
        assert_eq!(
            s,
            Step::Done {
                result: "if (x) { return 1; }".into()
            }
        );
    }

    // M6 (ТЗ §9): событие аудита пишется на каждый tool call.
    #[test]
    fn audit_sink_records_rejection() {
        struct Counter(usize);
        impl ToolAuditSink for Counter {
            fn record(&mut self, a: &ToolAudit) -> Result<()> {
                assert!(a.rejected);
                self.0 += 1;
                Ok(())
            }
        }
        let al = Allowlist::default();
        let mut c = Counter(0);
        // без sandbox: проверяем только путь allowlist-отказа
        let tc = ToolCall {
            tool: "run_shell".into(),
            args: json!({"command": "rm -rf /"}),
        };
        let audit = ToolAudit {
            tool: tc.tool.clone(),
            command: Some("rm -rf /".into()),
            rejected: true,
            reason: Some(al.check("rm -rf /").unwrap_err().to_string()),
            ..Default::default()
        };
        c.record(&audit).unwrap();
        assert_eq!(c.0, 1);
    }

    // P0-2: путь не должен позволять command injection.
    #[test]
    fn workspace_path_rejects_command_injection() {
        let cases = [
            "x; rm -rf /",
            "x && rm -rf /",
            "x | tee /tmp/pwned",
            "x > /tmp/pwned",
            "x < /etc/passwd",
            "`whoami`",
            "$(whoami)",
            "a b\nc",
            "a\rb",
            "../secret",
            "/etc/passwd",
            "",
        ];
        for p in cases {
            assert!(
                validate_workspace_path(p).is_err(),
                "путь {p:?} должен быть отклонён"
            );
        }
    }

    #[test]
    fn workspace_path_accepts_plain_relative_paths() {
        for p in ["Cargo.toml", "src/main.rs", "a/b/c.txt", ".env.example"] {
            assert!(
                validate_workspace_path(p).is_ok(),
                "путь {p:?} должен быть принят"
            );
        }
    }
}

//! Allowlist команд для sandbox (ТЗ v0.4 §4).
//!
//! **Deny by default.** Воркер запускает только команды, чьё первое слово есть
//! в allowlist. Allowlist задаётся через env `WORKER_ALLOWED_COMMANDS`
//! (comma-separated) и **никогда** не расширяется из LLM.
//!
//! Дополнительно (сверх ТЗ, защита в глубину):
//! - явный deny-список (`rm`, `sudo`, `curl`, …) — даже если попадёт в env;
//! - запрет shell-операторов (`>`, `|`, `;`, `&&`, `` ` ``, `$(`) — иначе
//!   `echo x; rm -rf /` обошёл бы проверку первого слова;
//! - запрет `..` в любом месте команды (выход из /workspace);
//! - **рекурсивная проверка** `bash -c "<команда>"` / `sh -c` — иначе
//!   `bash -c "rm -rf /"` прошёл бы по первому слову `bash`.

use crate::error::{Result, WorkerError};

/// Allowlist по умолчанию (ТЗ v0.4 §4).
pub const DEFAULT_ALLOWED: &[&str] = &[
    "bash", "cargo", "git", "cat", "ls", "echo", "mkdir", "touch",
];

/// Явно запрещённые команды — даже если попадут в env.
pub const EXPLICIT_DENY: &[&str] = &[
    "rm", "rmdir", "sudo", "su", "doas", "curl", "wget", "nc", "ncat", "netcat", "ssh", "scp",
    "sftp", "telnet", "dd", "mkfs", "shutdown", "reboot", "halt", "poweroff", "mount", "umount",
    "chmod", "chown", "chgrp", "kill", "pkill", "killall", "eval", "exec", "source", "apt",
    "apt-get", "dpkg", "pacman",
];

/// Shell-операторы, запрещённые в v0.4 (до analysis pipelines, ТЗ §4).
const FORBIDDEN_OPERATORS: &[&str] = &["|", ">", "<", ";", "&", "`", "$(", "${", "\n", "\r", "\\"];

/// Оболочки, для которых делается рекурсивная проверка `-c`.
const SHELLS: &[&str] = &["bash", "sh", "dash", "zsh"];

/// F11: флаги/опции, которыми `git`/`cargo` можно заставить выполнить
/// произвольный код в обход deny-списка и allowlist.
///
/// `git -c alias.x='!rm -rf /' x`, `git --exec-path=/tmp ...`,
/// `cargo --config build.rustc-wrapper=sh ...`, `cargo -Z...`. Даже при
/// наличии `git`/`cargo` в allowlist такие опции открывают RCE.
const DENIED_GIT_OPTS: &[&str] = &[
    "-c",
    "--config",
    "--exec-path",
    "--upload-pack",
    "--receive-pack",
];
const DENIED_CARGO_OPTS: &[&str] = &["--config", "-Z", "--rustc", "--wrapper"];

/// N5 (Волна 5.3): опасные опции конкретных подкоманд `git`.
///
/// `rebase` сам по себе безопасен (код не исполняет), но `-x`/`--exec`
/// запускают произвольную команду на каждом коммите — это RCE в обход
/// whitelist подкоманд. Найдено внешним аудитом: `git rebase -x id HEAD~1`
/// проходил все проверки.
const DENIED_GIT_SUBCMD_OPTS: &[(&str, &[&str])] =
    &[("rebase", &["--exec", "-x", "--interactive", "-i"])];

/// F11-доп (Волна 5.2): строгий whitelist ПОДКОМАНД `git`.
///
/// Чёрного списка опций недостаточно: `git config core.pager "sh -c ..."`
/// проходит проверку опций (второй токен `config` — не опция), а `git config`
/// умеет исполнять `alias.*=!...` и переопределять pager/hooks, то есть даёт
/// RCE в обход deny-списка команд. Поэтому переходим от blacklist к whitelist:
/// разрешены только заведомо безопасные read-only подкоманды, всё остальное
/// отклоняется по умолчанию (deny-by-default, как и весь sandbox).
const ALLOWED_GIT_SUBCMDS: &[&str] = &[
    "status",
    "diff",
    "log",
    "show",
    "rev-parse",
    "describe",
    "ls-files",
    "blame",
    "branch",
    "tag",
    "remote",
    "stash",
    "add",
    "commit",
    "checkout",
    "switch",
    "restore",
    "merge",
    "rebase",
    "cherry-pick",
    "revert",
    "reset",
    "push",
    "fetch",
    "pull",
    "clone",
    "init",
    "apply",
    "format-patch",
    "am",
];

/// F11-доп: строгий whitelist ПОДКОМАНД `cargo`.
///
/// `cargo` подкоманд-исполняемых обходов почти не имеет (его вектор — опции
/// `--config/-Z/--rustc/--wrapper`, уже закрытые), но whitelist убирает риск
/// будущих/неизвестных подкоманд вроде `cargo xtask` (произвольный код из
/// репозитория).
const ALLOWED_CARGO_SUBCMDS: &[&str] = &[
    "build", "check", "test", "run", "bench", "clippy", "fmt", "doc", "metadata", "tree", "clean",
    "update", "fetch", "add", "remove", "fix",
];

/// Максимальная глубина рекурсии для `bash -c "..."`.
const MAX_SHELL_DEPTH: usize = 3;

/// Allowlist команд.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Allowlist {
    allowed: Vec<String>,
}

impl Default for Allowlist {
    fn default() -> Self {
        Self::from_list(DEFAULT_ALLOWED)
    }
}

impl Allowlist {
    /// Собрать из списка (проверка нормализует регистр).
    pub fn from_list(items: &[&str]) -> Self {
        Self {
            allowed: items
                .iter()
                .map(|s| s.trim().to_lowercase())
                .filter(|s| !s.is_empty())
                .collect(),
        }
    }

    /// Собрать из строки env (comma-separated). Пусто → default.
    pub fn from_env_str(s: &str) -> Self {
        let items: Vec<&str> = s
            .split(',')
            .map(str::trim)
            .filter(|x| !x.is_empty())
            .collect();
        if items.is_empty() {
            Self::default()
        } else {
            Self::from_list(&items)
        }
    }

    /// Из окружения `WORKER_ALLOWED_COMMANDS` (или default).
    pub fn from_env() -> Self {
        match std::env::var("WORKER_ALLOWED_COMMANDS") {
            Ok(v) => Self::from_env_str(&v),
            Err(_) => Self::default(),
        }
    }

    /// Разрешено ли первое слово (без рекурсии). Публично для тестов.
    pub fn allows(&self, command: &str) -> bool {
        self.allowed.iter().any(|a| a == command)
    }

    /// Список разрешённых команд (для промпта Agent Loop).
    pub fn list(&self) -> Vec<String> {
        self.allowed.clone()
    }

    /// Полная проверка команды. `Ok(())` — можно запускать.
    pub fn check(&self, command: &str) -> Result<()> {
        self.check_depth(command, 0)
    }

    fn check_depth(&self, command: &str, depth: usize) -> Result<()> {
        let cmd = command.trim();
        if cmd.is_empty() {
            return Err(WorkerError::AllowlistRejected {
                command: command.to_string(),
                reason: "пустая команда".into(),
            });
        }
        if depth > MAX_SHELL_DEPTH {
            return Err(WorkerError::AllowlistRejected {
                command: command.to_string(),
                reason: "слишком глубокая вложенность shell -c".into(),
            });
        }

        // 1. Shell-операторы.
        for op in FORBIDDEN_OPERATORS {
            if cmd.contains(op) {
                return Err(WorkerError::AllowlistRejected {
                    command: command.to_string(),
                    reason: format!("запрещённый shell-оператор: {op:?}"),
                });
            }
        }

        // 2. Обход каталога + токенизация ЕДИНЫМ парсером (G2):
        //    quote-aware argv-парсер, тот же, что применяет sandbox.exec.
        //    Раньше allowlist шёл через split_whitespace, а sandbox — через
        //    собственный quote-aware парсер; расхождение на quoting было
        //    okном для обхода. Теперь источник истины один.
        let tokens: Vec<String> = parse_command_argv(cmd)?;
        if tokens.iter().any(|t| t.contains("..")) {
            return Err(WorkerError::AllowlistRejected {
                command: command.to_string(),
                reason: "путь с '..' запрещён".into(),
            });
        }

        let first = tokens[0].to_lowercase();

        // 3. Явный deny (в т.ч. абсолютный путь: /bin/rm → rm).
        let base = first.rsplit('/').next().unwrap_or(&first).to_string();
        if first.contains('/') && !trusted_executable(&first) {
            return Err(WorkerError::AllowlistRejected {
                command: command.to_string(),
                reason: "не доверенный путь executable".into(),
            });
        }
        if EXPLICIT_DENY.contains(&base.as_str()) {
            return Err(WorkerError::AllowlistRejected {
                command: command.to_string(),
                reason: format!("команда '{base}' в явном deny-списке"),
            });
        }

        // 4. Allowlist по первому слову.
        if !self.allows(&base) {
            return Err(WorkerError::AllowlistRejected {
                command: command.to_string(),
                reason: format!("'{base}' нет в allowlist"),
            });
        }

        // 5. Рекурсия для `bash -c "<внутренняя>"`.
        if SHELLS.contains(&base.as_str()) {
            let refs: Vec<&str> = tokens.iter().map(String::as_str).collect();
            let Some(inner) = extract_dash_c(&refs) else {
                return Err(WorkerError::AllowlistRejected {
                    command: command.to_string(),
                    reason: "shell разрешён только с однозначным -c".into(),
                });
            };
            return self.check_depth(&inner, depth + 1);
        }

        // 6. F11: конфигурационные опции git/cargo, позволяющие исполнить
        //    произвольный код в обход deny-списка.
        check_vcs_tool_options(&base, &tokens, command)?;
        // 7. F11-доп (Волна 5.2): строгий whitelist подкоманд. Опций мало:
        //    `git config core.pager "sh -c ..."` опций не содержит, но даёт RCE.
        check_vcs_tool_subcommands(&base, &tokens, command)?;

        Ok(())
    }
}

/// F11-доп (Волна 5.2): whitelist подкоманд `git`/`cargo`.
///
/// Закрывает вектор, который остался после F11: `git config` — это подкоманда,
/// а не опция, поэтому `check_vcs_tool_options` её не видит. Между тем
/// `git config core.pager "sh -c '...'"` или `git config alias.x '!...'`
/// исполняют произвольный код. Здесь разрешаем только известные безопасные
/// подкоманды (deny-by-default), а неизвестные/опасные (`config`, `daemon`,
/// `credential`, `filter-branch`, `submodule`, `xtask`…) отклоняем.
fn check_vcs_tool_subcommands(base: &str, tokens: &[String], command: &str) -> Result<()> {
    let allowed: &[&str] = match base {
        "git" => ALLOWED_GIT_SUBCMDS,
        "cargo" => ALLOWED_CARGO_SUBCMDS,
        _ => return Ok(()),
    };
    // Первый токен — сама команда; ищем подкоманду (первое слово без '-'),
    // пропуская глобальные опции И их аргументы (`git -C dir status`).
    let mut skip_next = false;
    let mut sub: Option<&str> = None;
    for t in tokens.iter().skip(1) {
        let t = t.as_str();
        if skip_next {
            skip_next = false;
            continue;
        }
        if t.starts_with('-') {
            // Опции, принимающие значение отдельным токеном.
            if matches!(t, "-C" | "-c" | "--git-dir" | "--work-tree" | "--namespace") {
                skip_next = true;
            }
            continue;
        }
        sub = Some(t);
        break;
    }
    let Some(sub) = sub else {
        // Нет подкоманды (например, `git` без аргументов) — не наша забота.
        return Ok(());
    };
    // Отбрасываем возможный путь: подкоманда вида `./evil` отклоняется.
    let sub_lc = sub.to_ascii_lowercase();
    if sub.contains('/') || !allowed.contains(&sub_lc.as_str()) {
        return Err(WorkerError::AllowlistRejected {
            command: command.to_string(),
            reason: format!("подкоманда {base} '{sub}' не в whitelist"),
        });
    }
    // N5 (Волна 5.3): адресно отклоняем исполняющие опции разрешённых подкоманд
    // (`git rebase -x/--exec`). Whitelist подкоманд их не ловит, т.к. `rebase`
    // сам по себе разрешён.
    if base == "git" {
        if let Some(denied) = DENIED_GIT_SUBCMD_OPTS
            .iter()
            .find(|(s, _)| *s == sub_lc.as_str())
            .map(|(_, opts)| *opts)
        {
            for t in tokens.iter().skip(1) {
                let raw = t.split('=').next().unwrap_or(t);
                for d in denied {
                    let hit = if let Some(_long) = d.strip_prefix("--") {
                        t == d || t.starts_with(&format!("{d}="))
                    } else {
                        // короткий флаг: точное совпадение, слитная форма
                        // (`-xcmd`) или кластер (`-ix cmd`).
                        raw == *d
                            || (raw.starts_with('-')
                                && !raw.starts_with("--")
                                && raw[1..].contains(&d[1..]))
                    };
                    if hit {
                        return Err(WorkerError::AllowlistRejected {
                            command: command.to_string(),
                            reason: format!("запрещённая опция {base} {sub_lc} '{t}'"),
                        });
                    }
                }
            }
        }
    }
    Ok(())
}

/// F11: запрет опасных опций `git`/`cargo` (config/exec-path/-Z/...).
///
/// Такие опции позволяют выполнить произвольный код (`git -c alias.x=!sh`,
/// `cargo --config build.rustc-wrapper=...`), обходя deny-список команд.
/// Проверяем и точное совпадение опции, и форму `--opt=value`, и `-cvalue`.
fn check_vcs_tool_options(base: &str, tokens: &[String], command: &str) -> Result<()> {
    let denied: &[&str] = match base {
        "git" => DENIED_GIT_OPTS,
        "cargo" => DENIED_CARGO_OPTS,
        _ => return Ok(()),
    };
    // Первый токен — сама команда; смотрим остальные.
    for t in tokens.iter().skip(1) {
        // Длинные опции сравниваем без учёта регистра (у них регистр незначим).
        // КОРОТКИЕ флаги — С УЧЁТОМ РЕГИСТРА (N1): иначе `git -C <dir>`
        // (сменить каталог, легитимно) ложно совпадал с запрещённым `-c`
        // после приведения к нижнему регистру и отклонялся.
        let raw_opt = t.split('=').next().unwrap_or(t);
        let opt = raw_opt.to_ascii_lowercase();
        for d in denied {
            let is_short = d.len() == 2 && d.starts_with('-') && !d.starts_with("--");
            let matched = if is_short {
                // `-c` запрещён, но `-C` разрешён; `-cfoo` (слитная форма) запрещён.
                raw_opt == *d || (raw_opt.starts_with(d) && raw_opt.len() > d.len())
            } else {
                opt == d.to_ascii_lowercase()
            };
            if matched {
                return Err(WorkerError::AllowlistRejected {
                    command: command.to_string(),
                    reason: format!("запрещённая опция {base} '{t}'"),
                });
            }
        }
    }
    Ok(())
}

/// Единый argv-парсер команд (G2).
///
/// Разбирает небольшой argv-язык: пробелы разделяют токены, одинарные и
/// двойные кавычки группируют; shell-операторы и escape **отвергаются**, а не
/// интерпретируются. Один и тот же парсер использует и allowlist-политика, и
/// `sandbox.exec` — чтобы не было двух расходящихся мнений о том, где границы
/// токенов.
///
/// Возвращает `Err`, если обнаружен запрещённый символ (`; | & < > ` $ \`),
/// незакрытая кавычка или пустая команда.
pub fn parse_command_argv(command: &str) -> Result<Vec<String>> {
    let mut argv = Vec::new();
    let mut token = String::new();
    let mut quote = None;
    let mut started = false;
    for ch in command.chars() {
        match quote {
            Some(q) if ch == q => quote = None,
            Some(_) => token.push(ch),
            None if ch == '\'' || ch == '"' => {
                quote = Some(ch);
                started = true;
            }
            None if ch.is_whitespace() => {
                if started {
                    argv.push(std::mem::take(&mut token));
                    started = false;
                }
            }
            None if matches!(ch, ';' | '|' | '&' | '<' | '>' | '`' | '$' | '\\') => {
                return Err(WorkerError::AllowlistRejected {
                    command: command.to_string(),
                    reason: format!("запрещённый shell-символ: {ch:?}"),
                });
            }
            None => {
                token.push(ch);
                started = true;
            }
        }
    }
    if quote.is_some() {
        return Err(WorkerError::AllowlistRejected {
            command: command.to_string(),
            reason: "незакрытая кавычка".into(),
        });
    }
    if started {
        argv.push(token);
    }
    if argv.is_empty() {
        return Err(WorkerError::AllowlistRejected {
            command: command.to_string(),
            reason: "пустая команда".into(),
        });
    }
    Ok(argv)
}

fn trusted_executable(path: &str) -> bool {
    matches!(
        path,
        "/bin/bash" | "/usr/bin/bash" | "/bin/sh" | "/usr/bin/sh"
    )
}

/// Извлечь аргумент `-c` из токенов (`["bash","-c","rm -rf /"]` → `rm -rf /`).
///
/// Поддерживает `-c "cmd"` (уже разбито по пробелам — склеиваем хвост) и
/// `-c cmd`.
fn extract_dash_c(tokens: &[&str]) -> Option<String> {
    // Reject combined flags (-lc/-xc), script operands and options before -c.
    if tokens.len() < 3 || tokens[1] != "-c" || tokens.iter().filter(|t| **t == "-c").count() != 1 {
        return None;
    }
    let rest = &tokens[2..];
    if rest.is_empty() {
        return None;
    }
    // Склеиваем оставшееся: кавычки снимает shell, но в тестах строка приходит
    // уже разбитой, поэтому восстанавливаем по пробелу.
    let mut s = rest.join(" ");
    s = s.trim().to_string();
    // Снять обёртывающие кавычки: `"cargo test"` → `cargo test`.
    let quoted =
        (s.starts_with('"') && s.ends_with('"')) || (s.starts_with('\'') && s.ends_with('\''));
    if quoted && s.len() >= 2 {
        s = s[1..s.len() - 1].to_string();
    }
    if s.trim().is_empty() {
        return None;
    }
    Some(s)
}

#[cfg(test)]
mod mutants_deep_tests;

#[cfg(test)]
mod allowlist_layers_tests;

#[cfg(test)]
mod tests {
    use super::*;

    fn al() -> Allowlist {
        Allowlist::default()
    }

    // §8.1.1
    #[test]
    fn allowlist_accepts_cargo() {
        assert!(al().check("cargo test").is_ok());
        assert!(al().check("cargo build --release").is_ok());
        assert!(al().check("git status").is_ok());
        assert!(al().check("ls -la").is_ok());
    }

    // §8.1.2
    #[test]
    fn allowlist_rejects_rm() {
        let e = al().check("rm -rf /").unwrap_err();
        assert!(
            matches!(e, WorkerError::AllowlistRejected { .. }),
            "got {e:?}"
        );
        assert!(al().check("rm file.txt").is_err());
        // абсолютный путь тоже ловится
        assert!(al().check("/bin/rm -rf /").is_err());
    }

    // §8.1.3
    #[test]
    fn allowlist_rejects_sudo() {
        assert!(al().check("sudo ls").is_err());
        assert!(al().check("su - root").is_err());
    }

    // §8.1.4
    #[test]
    fn allowlist_rejects_network_cmds() {
        for c in [
            "curl http://x",
            "wget http://x",
            "nc -l 1234",
            "ssh host",
            "scp a b",
        ] {
            assert!(al().check(c).is_err(), "{c} должен быть отклонён");
        }
    }

    // Сверх ТЗ: shell-операторы (иначе `echo x; rm -rf /` обходит проверку).
    #[test]
    fn allowlist_rejects_shell_operators() {
        for c in [
            "ls > out.txt",
            "ls | grep x",
            "echo a; rm -rf /",
            "echo a && rm -rf /",
            "echo `whoami`",
            "echo $(whoami)",
        ] {
            assert!(al().check(c).is_err(), "{c} должен быть отклонён");
        }
    }

    // Сверх ТЗ: обход через `bash -c`.
    #[test]
    fn allowlist_rejects_bash_c_bypass() {
        assert!(
            al().check("bash -c \"rm -rf /\"").is_err(),
            "bash -c rm должен быть отклонён"
        );
        assert!(al().check("bash -c \"curl http://x\"").is_err());
        // легитимный bash -c с разрешённой командой проходит
        assert!(al().check("bash -c \"cargo test\"").is_ok());
    }

    // Сверх ТЗ: выход из /workspace.
    #[test]
    fn allowlist_rejects_path_traversal() {
        assert!(al().check("cat ../../etc/passwd").is_err());
        assert!(al().check("ls ../").is_err());
    }

    #[test]
    fn allowlist_from_env_str() {
        let a = Allowlist::from_env_str("cargo, git ,ls");
        // F11-доп: whitelist подкоманд сузил «любой cargo/git» до известных
        // подкоманд, поэтому проверяем на реальных.
        assert!(a.check("cargo test").is_ok());
        assert!(a.check("git status").is_ok());
        assert!(a.check("bash z").is_err(), "bash не в кастомном списке");
        // пусто → default; shell без явного -c запрещён.
        assert!(Allowlist::from_env_str("").check("bash x").is_err());
    }

    #[test]
    fn allowlist_empty_command_rejected() {
        assert!(al().check("").is_err());
        assert!(al().check("   ").is_err());
    }

    #[test]
    fn allowlist_rejects_shell_options_and_escaped_operators() {
        assert!(al().check("bash -lc 'rm -rf /'").is_err());
        assert!(al().check("echo foo\\; rm -rf /").is_err());
        assert!(al().check("echo ${HOME}").is_err());
    }

    // P0-1: shell-форма без однозначного `-c` — скрипт, интерактив, голый shell.
    #[test]
    fn allowlist_rejects_shell_script_operand() {
        for c in [
            "bash script.sh", // script operand вместо -c
            "sh /tmp/x.sh",
            "bash",    // голый shell
            "bash -i", // интерактивный shell
            "bash --login",
        ] {
            assert!(al().check(c).is_err(), "{c} должен быть отклонён");
        }
    }

    // P0-1: проверка доверенного executable path, а не только basename.
    #[test]
    fn allowlist_rejects_untrusted_executable_path() {
        assert!(
            al().check("/tmp/cargo build").is_err(),
            "basename cargo, но путь недоверенный"
        );
        assert!(al().check("./cargo build").is_err());
        assert!(al().check("/usr/local/bin/git status").is_err());
        assert!(al().check("../cargo build").is_err());
        // доверенный путь shell с -c проходит
        assert!(al().check("/bin/bash -c \"cargo test\"").is_ok());
    }

    // P0-1: комбинированные флаги и env-подстановки.
    #[test]
    fn allowlist_rejects_combined_flags_and_env_substitution() {
        assert!(al().check("bash -xc 'cargo test'").is_err());
        assert!(al().check("bash -ec 'cargo test'").is_err());
        assert!(al().check("cat ${HOME}/.ssh/id_rsa").is_err());
        assert!(al().check("cat $(whoami)").is_err());
    }

    // G2 (audit): политика и sandbox используют ОДИН argv-парсер.
    // Регрессия: до унификации allowlist шёл через split_whitespace и не
    // видел, что `echo "hello world"` — это один токен; теперь видит.
    #[test]
    fn single_argv_parser_shared_with_sandbox() {
        assert_eq!(
            parse_command_argv("echo 'hello world'").unwrap(),
            vec!["echo".to_string(), "hello world".to_string()]
        );
        // Кавычки больше не считаются «неоднозначным quoting» — это часть
        // единого argv-языка, а не признак инъекции.
        assert!(al().check("echo 'a b'").is_ok());
        // А shell-символы внутри/вне кавычек по-прежнему отсекаются.
        assert!(al().check("echo 'a; rm -rf /'").is_err());
        assert!(al().check("echo `id`").is_err());
    }

    // ---------- F11: конфигурационные опции git/cargo ----------

    #[test]
    fn f11_rejects_git_config_option() {
        // git -c alias.x=!rm -rf / x  -> RCE обход
        assert!(
            al().check("git -c alias.x=!rm -rf / x").is_err(),
            "git -c должен быть отклонён"
        );
        assert!(al().check("git --config core.pager=sh status").is_err());
    }

    #[test]
    fn f11_rejects_git_exec_path() {
        assert!(al().check("git --exec-path=/tmp status").is_err());
        assert!(al().check("git --upload-pack=/tmp/evil fetch").is_err());
    }

    #[test]
    fn f11_rejects_cargo_config_option() {
        // cargo --config build.rustc-wrapper=sh build -> RCE
        assert!(
            al().check("cargo --config build.rustc-wrapper=sh build")
                .is_err(),
            "cargo --config должен быть отклонён"
        );
        assert!(al().check("cargo -Z build-std build").is_err());
    }

    #[test]
    fn f11_allows_plain_git_and_cargo() {
        assert!(al().check("git status").is_ok());
        assert!(al().check("git commit -m 'x'").is_ok());
        assert!(al().check("cargo test").is_ok());
        assert!(al().check("cargo build --release").is_ok());
        // обычные флаги не задеваются
        assert!(al().check("git log --oneline -5").is_ok());
        assert!(al().check("cargo test --features shell-tools").is_ok());
    }

    // ---------- F11-доп (Волна 5.2): whitelist подкоманд ----------

    #[test]
    fn f11d_rejects_git_config_subcommand() {
        // Вектор из аудита: подкоманда `config` исполняет `alias.x=!...` и
        // переопределяет pager -> RCE. Опций здесь нет, поэтому старый
        // check_vcs_tool_options его пропускал.
        assert!(
            al().check("git config core.pager 'sh -c evil'").is_err(),
            "git config должен быть отклонён как подкоманда"
        );
        assert!(al().check("git config alias.x '!rm -rf /'").is_err());
        // Глобальная опция перед подкомандой не должна создавать лазейку.
        assert!(al().check("git -C /workspace config user.name x").is_err());
    }

    #[test]
    fn f11d_rejects_dangerous_git_subcommands() {
        for cmd in [
            "git daemon --reuseaddr --base-path=/ --export-all",
            "git credential fill",
            "git filter-branch --tree-filter 'sh -c evil' HEAD",
            "git submodule add /tmp/evil",
        ] {
            assert!(al().check(cmd).is_err(), "должно быть отклонено: {cmd}");
        }
    }

    #[test]
    fn f11d_rejects_non_whitelisted_cargo_subcommands() {
        // `cargo xtask` исполняет произвольный код из репозитория.
        assert!(al().check("cargo xtask evil").is_err());
        assert!(al().check("cargo install evil-crate").is_err());
    }

    #[test]
    fn f11d_allows_whitelisted_subcommands_with_global_opts() {
        // Глобальные опции и легитимные подкоманды не задеваются.
        assert!(al().check("git -C /workspace status").is_ok());
        assert!(al().check("git --no-pager log").is_ok());
        assert!(al().check("cargo test --release").is_ok());
        assert!(al().check("cargo clippy -- -D warnings").is_ok());
    }

    // ---------- N5 (Волна 5.3): опасные опции подкоманд git ----------

    #[test]
    fn n5_rejects_git_rebase_exec() {
        // Найдено внешним аудитом (Claude, проверено запуском): `git rebase`
        // разрешён как подкоманда, но `-x`/`--exec` исполняют переданную команду
        // на каждом коммите, а `-i`/`--interactive` позволяет вписать `exec`
        // в todo-лист — RCE в обход whitelist подкоманд.
        for cmd in [
            "git rebase -x id HEAD~1",
            "git rebase --exec 'id' HEAD~1",
            "git rebase --exec=id HEAD~1",
            "git rebase -i -x sh HEAD~3",
            "git rebase --interactive -xevil HEAD~3",
            "git rebase -i HEAD~3",
            "git rebase --interactive HEAD~3",
            "git rebase -ix sh HEAD~2",
        ] {
            assert!(al().check(cmd).is_err(), "должно быть отклонено: {cmd}");
        }
    }

    #[test]
    fn n5_allows_plain_rebase() {
        // Безопасные (не-исполняющие) формы rebase не задеваются.
        assert!(al().check("git rebase main").is_ok());
        assert!(al().check("git rebase --continue").is_ok());
        assert!(al().check("git rebase --abort").is_ok());
        assert!(al().check("git rebase --onto main base topic").is_ok());
        assert!(al().check("git rebase --autostash main").is_ok());
    }
}

//! Тесты слоёв allowlist: каждый убивает ровно один одиночный мутант.
//! Подключение: `#[cfg(test)] mod allowlist_layers_tests;` рядом с allowlist.rs
//! (или в `mod tests`). Используется только публичный API: Allowlist::{default, from_env_str, check}.
//!
//! Мутанты (проверены запуском на живом allowlist.rs, по одному):
//!   L1  убрана проверка EXPLICIT_DENY            -> убивает l1_*
//!   L7  убрана проверка членства в allowlist     -> убивает l7_*
//!   L8  убран запрет перевода строки '\n'        -> убивает l8_*
//!   L10 убраны запреты '$(' и '${'               -> убивает l10_*
//!
//! Про L6/L9/L11/L12 (уточнено после проб на живом коде, обе стороны правы):
//! они безопасно ДУБЛИРУЮТСЯ разбором для опасных случаев (оператор вне
//! кавычек: `bash -c "echo a & rm x"` отклоняется и без слоя списка — уже на
//! токенизации), но различаются для ОПЕРАТОРА-ЛИТЕРАЛА В КАВЫЧКАХ
//! (`bash -c 'echo "a & b"'`): разбор его пропускает, удерживает лишь слой
//! FORBIDDEN_OPERATORS. Убить L9/L11/L12 можно только такими кейсами (см.
//! mutants_deep_tests.rs), и это закрепляет КОНСЕРВАТИВНУЮ политику: честное
//! `echo "a > b"` тоже отклоняется. Политика выбрана осознанно (гейт security,
//! ложный отказ дешевле обхода). L6 (глубина) — оставлен как есть: без
//! обратного слэша вложенность кавычек не глубже двух.
use super::Allowlist;

fn ok(al: &Allowlist, c: &str) {
    assert!(al.check(c).is_ok(), "должно быть разрешено: {c:?}");
}
fn no(al: &Allowlist, c: &str) {
    assert!(al.check(c).is_err(), "должно быть отклонено: {c:?}");
}

/// Положительный контроль: набор «всё отклоняем» эти тесты не пройдёт.
#[test]
fn controls_legit_commands_pass() {
    let al = Allowlist::default();
    for c in [
        "echo hello",
        "cat Cargo.toml",
        "ls -la",
        "cargo build",
        "cargo test",
        "git status",
        "git diff",
        "bash -c \"echo ok\"",
    ] {
        ok(&al, c);
    }
}

/// L7: команды, которых нет ни в deny-списке, ни в allowlist. Убирает только проверка членства.
#[test]
fn l7_unlisted_programs_are_rejected_by_membership() {
    let al = Allowlist::default();
    for c in [
        "python3 -c pass",
        "find . -name x",
        "perl -e 1",
        "node -e 1",
        "ruby -e 1",
        "awk 1 file",
    ] {
        no(&al, c);
    }
}

/// L1: deny-список обязан побеждать allowlist. Включаем `rm` в allowlist явно:
/// без слоя EXPLICIT_DENY команда прошла бы.
#[test]
fn l1_explicit_deny_beats_allowlist() {
    let al = Allowlist::from_env_str("rm,cat,ls,echo");
    no(&al, "rm -rf x");
    ok(&al, "cat Cargo.toml"); // контроль: allowlist при этом работает
}

/// L8: перевод строки внутри `bash -c` исполнился бы как вторая команда.
#[test]
fn l8_newline_inside_bash_c_is_rejected() {
    let al = Allowlist::default();
    no(&al, "bash -c \"echo a\nrm -rf x\"");
    no(&al, "bash -c 'echo a\rrm -rf x'");
}

/// L10: подстановка внутри двойных кавычек во вложенной строке: парсер её пропускает,
/// удерживает только список операторов.
#[test]
fn l10_command_substitution_in_nested_quotes_is_rejected() {
    let al = Allowlist::default();
    no(&al, "bash -c 'echo \"$(rm -rf x)\"'");
    no(&al, "bash -c 'echo \"${HOME}\"'");
    no(&al, "bash -c 'echo \"`id`\"'");
}

/// Арбитр для белого списка подкоманд git/cargo (v0.5.2). Красный на v0.5.1 (git config проходит),
/// зелёный после правки. Это поведенческий тест, не проверка текста.
#[test]
fn git_and_cargo_config_injection_vectors_are_rejected() {
    let al = Allowlist::default();
    for c in [
        "git config core.pager sh",
        "git config --global alias.x '!id'",
        "git -c core.pager=sh log",
        "cargo --config build.rustc-wrapper=sh build",
        "cargo -Z unstable-options build",
    ] {
        no(&al, c);
    }
    // контроль: безопасные подкоманды живы
    for c in [
        "git status",
        "git log",
        "git diff",
        "git add .",
        "git commit -m x",
        "cargo build",
        "cargo test",
    ] {
        ok(&al, c);
    }
}

//! Тесты мутантов L9/L11/L12 — разделяющие кейсы «оператор-литерал в кавычках».
//!
//! УТОЧНЕНИЕ ПОСЛЕ ПРОГОНОВ НА ЖИВОМ КОДЕ (важно для карты мутантов):
//! кейсы вида `echo ok & echo evil` (оператор ВНЕ кавычек) мутанта L9/L11/L12
//! НЕ убивают: там символ вне кавычек, и строка отклоняется разбором argv даже
//! после удаления оператора из `FORBIDDEN_OPERATORS`. Убивает только кейс, где
//! оператор — ЛИТЕРАЛ В КАВЫЧКАХ внутри вложенной строки (`bash -c 'echo "a & b"'`):
//! разбор его пропускает (символ внутри кавычек), удерживает лишь слой списка.
//!
//! НЕ ПУТАТЬ с предложением Gemini («l9_background_and_operator_is_rejected_early»):
//! его формулировка утверждала, что операторы вне кавычек убивают мутанта — это
//! неверно, такие кейсы не различают слой и дают ложное чувство покрытия.
use super::Allowlist;

fn no(al: &Allowlist, c: &str) {
    assert!(
        al.check(c).is_err(),
        "команда обязана быть отклонена: {c:?}"
    );
}
fn ok(al: &Allowlist, c: &str) {
    assert!(al.check(c).is_ok(), "команда обязана быть разрешена: {c:?}");
}

/// L9: мутант убирает `&` из `FORBIDDEN_OPERATORS`.
/// Убивает только оператор-ЛИТЕРАЛ в кавычках — разбор его пропускает.
#[test]
fn l9_ampersand_killed_only_by_quoted_literal() {
    let al = Allowlist::default();
    // различающий кейс: `&` внутри вложенной строки, но в кавычках
    no(&al, "bash -c 'echo \"a & b\"'");
    no(&al, "bash -c \"echo 'a && b'\"");
}

/// L11: мутант убирает `|`.
#[test]
fn l11_pipe_killed_only_by_quoted_literal() {
    let al = Allowlist::default();
    no(&al, "bash -c 'echo \"a | b\"'");
    no(&al, "bash -c \"echo 'x || y'\"");
}

/// L12: мутант убирает `>` (и `<`).
#[test]
fn l12_redirection_killed_only_by_quoted_literal() {
    let al = Allowlist::default();
    no(&al, "bash -c 'echo \"a > b\"'");
    no(&al, "bash -c 'echo \"a < b\"'");
}

/// Контроль политики: опасные случаи (вне кавычек) отклоняются, как и раньше —
/// но подчёркиваем, что это НЕ доказательство убийства мутанта L9/L11/L12.
#[test]
fn dangerous_out_of_quote_forms_still_rejected() {
    let al = Allowlist::default();
    no(&al, "echo ok & echo evil");
    no(&al, "cargo test & rm -rf target");
    no(&al, "cat Cargo.toml | sh");
    no(&al, "echo evil > /workspace/.cargo/config.toml");
}

/// Положительный контроль: литералы БЕЗ операторов не должны ложно отсекаться
/// сверх политики. `echo "a b"` (пробел в кавычках) проходит.
#[test]
fn benign_quoted_literals_still_pass() {
    let al = Allowlist::default();
    ok(&al, "echo 'a b'");
    ok(&al, "git commit -m 'fix: a b'");
}

/// Арбитр песочницы: обход через флаги конфигурации cargo.
#[test]
fn cargo_extended_flags_and_aliases_are_rejected() {
    let al = Allowlist::default();
    no(
        &al,
        "cargo --config target.x86_64-unknown-linux-gnu.runner='sh' test",
    );
    no(&al, "cargo -Z build-std build");
    ok(&al, "cargo build --release");
    ok(&al, "cargo test --workspace");
    ok(&al, "cargo clippy -- -D warnings");
}

//! Сохранение артефакта на диск: content-addressable по sha256, атомарная запись.

use crate::error::{Result, WorkerError};
use sha2::{Digest, Sha256};
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

/// Путь к файлу артефакта по его ref (`sha256:<hex>` → `<dir>/<hex>.txt`).
pub fn artifact_path(dir: &Path, artifact_ref: &str) -> PathBuf {
    let hex = artifact_ref.strip_prefix("sha256:").unwrap_or(artifact_ref);
    dir.join(format!("{hex}.txt"))
}

/// sha256 содержимого в виде `sha256:<hex>`.
pub fn sha256_ref(content: &[u8]) -> String {
    let mut h = Sha256::new();
    h.update(content);
    format!("sha256:{:x}", h.finalize())
}

/// Прочитать файл и сверить его sha256 с ожидаемым ref.
///
/// Используется после записи, а также тестами для проверки подмены файла.
pub fn verify_artifact(path: &Path, expected_ref: &str) -> Result<()> {
    let bytes =
        std::fs::read(path).map_err(|e| WorkerError::Artifact(format!("read {path:?}: {e}")))?;
    let got = sha256_ref(&bytes);
    if got != expected_ref {
        return Err(WorkerError::Artifact(format!(
            "sha256 mismatch: expected {expected_ref}, got {got}"
        )));
    }
    Ok(())
}

/// Атомарно записать артефакт. Возвращает `(ref, path, size)`.
///
/// - Если файл уже существует с тем же именем — **не перезаписываем**
///   (content-addressable: одно содержимое = один файл).
/// - Запись идёт в `.tmp.<pid>`, затем `rename` (атомарно на POSIX).
/// - После записи файл перечитывается, sha256 сверяется с ref.
pub fn write_artifact(dir: &Path, content: &[u8]) -> Result<(String, PathBuf, u64)> {
    std::fs::create_dir_all(dir)
        .map_err(|e| WorkerError::Artifact(format!("create_dir_all {dir:?}: {e}")))?;

    let reference = sha256_ref(content);
    let final_path = artifact_path(dir, &reference);

    if final_path.exists() {
        // Уже есть — идемпотентность, не трогаем. Но имя = хэш содержимого:
        // если файл повреждён/подменён, честно сообщаем об ошибке (M2).
        verify_artifact(&final_path, &reference)?;
        let size = std::fs::metadata(&final_path)
            .map_err(|e| WorkerError::Artifact(format!("stat {final_path:?}: {e}")))?
            .len();
        return Ok((reference, final_path, size));
    }

    let nonce = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or_default();
    let tmp = dir.join(format!(
        "{}.tmp.{}.{}",
        final_path.file_name().unwrap().to_string_lossy(),
        std::process::id(),
        nonce
    ));
    let result: std::result::Result<(), WorkerError> = (|| {
        use std::io::Write;
        let mut file = std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&tmp)
            .map_err(|e| WorkerError::Artifact(format!("create {tmp:?}: {e}")))?;
        file.write_all(content)
            .map_err(|e| WorkerError::Artifact(format!("write {tmp:?}: {e}")))?;
        file.sync_all()
            .map_err(|e| WorkerError::Artifact(format!("sync {tmp:?}: {e}")))?;
        std::fs::rename(&tmp, &final_path)
            .map_err(|e| WorkerError::Artifact(format!("rename {tmp:?} -> {final_path:?}: {e}")))?;
        Ok(())
    })();
    if result.is_err() {
        let _ = std::fs::remove_file(&tmp);
    }
    result?;

    // Проверка sha256 после записи.
    verify_artifact(&final_path, &reference)?;
    let size = std::fs::metadata(&final_path)
        .map_err(|e| WorkerError::Artifact(format!("stat {final_path:?}: {e}")))?
        .len();

    Ok((reference, final_path, size))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tmpdir(tag: &str) -> PathBuf {
        let d = std::env::temp_dir().join(format!(
            "swarm_worker_test_{tag}_{}_{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(&d).unwrap();
        d
    }

    #[test]
    fn artifact_path_from_ref() {
        let p = artifact_path(Path::new("/var/swarm/artifacts"), "sha256:ab12cd");
        assert_eq!(p, PathBuf::from("/var/swarm/artifacts/ab12cd.txt"));
        // без префикса — тоже работает
        let p2 = artifact_path(Path::new("/x"), "deadbeef");
        assert_eq!(p2, PathBuf::from("/x/deadbeef.txt"));
    }

    #[test]
    fn atomic_write_leaves_no_tmp() {
        let dir = tmpdir("atomic");
        let (reference, path, size) = write_artifact(&dir, b"hello world").unwrap();
        assert!(reference.starts_with("sha256:"));
        assert_eq!(size, 11);
        assert!(path.exists());
        // .tmp-файлов не осталось
        let leftovers: Vec<_> = std::fs::read_dir(&dir)
            .unwrap()
            .filter_map(|e| e.ok())
            .filter(|e| e.file_name().to_string_lossy().contains(".tmp."))
            .collect();
        assert!(leftovers.is_empty(), "остались tmp-файлы: {leftovers:?}");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn sha256_matches() {
        let dir = tmpdir("match");
        let (reference, path, _) = write_artifact(&dir, b"payload").unwrap();
        let on_disk = std::fs::read(&path).unwrap();
        assert_eq!(sha256_ref(&on_disk), reference);
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn sha256_mismatch_fails() {
        let dir = tmpdir("mismatch");
        // (а) целостный файл проходит проверку
        let (reference, path, _) = write_artifact(&dir, b"payload").unwrap();
        verify_artifact(&path, &reference).unwrap();

        // (б) подмена содержимого ломает прямую проверку
        std::fs::write(&path, b"tampered").unwrap();
        assert!(
            verify_artifact(&path, &reference).is_err(),
            "подмена файла должна ломать sha256-проверку"
        );

        // (в) и тот же инвариант на пути write_artifact: если по адресу
        //     (имя = sha256) лежит повреждённый файл — ошибка, а не тихое «ок».
        let dir2 = tmpdir("mismatch2");
        let content = b"expected-content";
        let ref2 = sha256_ref(content);
        let p2 = artifact_path(&dir2, &ref2);
        std::fs::write(&p2, b"corrupted").unwrap();
        let err = write_artifact(&dir2, content);
        assert!(
            err.is_err(),
            "write_artifact обязан заметить повреждённый файл по адресу-хэшу"
        );

        let _ = std::fs::remove_dir_all(&dir);
        let _ = std::fs::remove_dir_all(&dir2);
    }

    #[test]
    fn existing_file_not_overwritten() {
        let dir = tmpdir("idem");
        let (r1, p1, _) = write_artifact(&dir, b"same").unwrap();
        let mtime1 = std::fs::metadata(&p1).unwrap().modified().unwrap();
        std::thread::sleep(std::time::Duration::from_millis(10));
        let (r2, p2, _) = write_artifact(&dir, b"same").unwrap();
        assert_eq!(r1, r2);
        assert_eq!(p1, p2);
        let mtime2 = std::fs::metadata(&p2).unwrap().modified().unwrap();
        assert_eq!(
            mtime1, mtime2,
            "существующий файл не должен перезаписываться"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }
}

//! Аудит tool calls в журнал событий (ТЗ v0.4 §7).
//!
//! Пишем **только hash и размер** вывода, не полный текст.
//!
//! Важно: прямой `append_event` воркеру недоступен by design (см.
//! `step2/roles.sql` §6 — «журнал нельзя подделать снаружи»). Поэтому sink
//! вызывает SECURITY DEFINER-функцию `record_tool_call`, которая проверяет
//! живую аренду и пишет событие от имени `swarm_owner`
//! (`step2/roles_patch_tool_call_audit.sql`).

use crate::agent_loop::{ToolAudit, ToolAuditSink};
use crate::error::{Result, WorkerError};
use postgres::{Client, NoTls};
use uuid::Uuid;

/// Пишет событие `tool_call` в `events` через `record_tool_call`.
pub struct PgAuditSink {
    client: Client,
    task_id: Uuid,
    worker_id: String,
    epoch: i64,
    seq: u64,
}

impl PgAuditSink {
    /// Отдельное соединение к той же БД, что и воркер.
    pub fn connect(dsn: &str, task_id: Uuid, worker_id: &str, epoch: i64) -> Result<Self> {
        let client = Client::connect(dsn, NoTls)
            .map_err(|e| WorkerError::Database(swarm_core::DispatcherError::from_pg(e)))?;
        Ok(Self {
            client,
            task_id,
            worker_id: worker_id.to_string(),
            epoch,
            seq: 0,
        })
    }
}

impl ToolAuditSink for PgAuditSink {
    fn record(&mut self, a: &ToolAudit) -> Result<()> {
        self.seq += 1;
        let event_id = format!("tool_call_{}", self.seq);
        // §7: команда + exit_code + длительность + hash вывода + размер.
        let payload = serde_json::json!({
            "tool": a.tool,
            "command": a.command,
            "exit_code": a.exit_code,
            "duration_ms": a.duration_ms as i64,
            "output_hash": a.output_sha256,
            "output_bytes": a.output_bytes,
            "truncated": a.truncated,
            "rejected": a.rejected,
            "reason": a.reason,
        });
        self.client
            .execute(
                "select record_tool_call($1, $2, $3, $4, $5)",
                &[
                    &self.task_id,
                    &self.worker_id,
                    &self.epoch,
                    &event_id,
                    &payload,
                ],
            )
            .map_err(|e| WorkerError::Database(swarm_core::DispatcherError::from_pg(e)))?;
        Ok(())
    }
}

/// Посчитать события `tool_call` по задаче (для тестов/диагностики).
pub fn count_tool_calls(dsn: &str, task_id: Uuid) -> Result<i64> {
    let mut c = Client::connect(dsn, NoTls)
        .map_err(|e| WorkerError::Database(swarm_core::DispatcherError::from_pg(e)))?;
    let row = c
        .query_one(
            "select count(*) from events where task_id = $1 and kind = 'tool_call'",
            &[&task_id],
        )
        .map_err(|e| WorkerError::Database(swarm_core::DispatcherError::from_pg(e)))?;
    Ok(row.get(0))
}

//! Hard budget guard (Issue #3).
//!
//! Три независимых предохранителя против «бесконечной траты денег»:
//!
//! 1. **Глобальный лимит** `MAX_TOTAL_COST_USD` — суммарная стоимость всех
//!    LLM-вызовов (из cost ledger, Issue #2). Проверяется ПЕРЕД каждым вызовом.
//! 2. **Лимит задачи** `budget_cap` (в токенах) — уже есть в схеме, здесь лишь
//!    вынесен в явную проверку.
//! 3. **Circuit breaker на авторизацию** — HTTP 401/403 означает, что ключ
//!    невалиден: повторять бессмысленно (инцидент argo-memory: 4 часа пустых
//!    попыток). Такой вызов блокирует задачу немедленно и не ретраится.
//!
//! Плюс автоматическое отключение воркера после N подряд неудач (`should_disable`).

/// Денежные величины сравниваем в целых нанодолларах, чтобы не зависеть от
/// погрешности f64 и не терять мелкие расходы: 1 = $0.000000001.
///
/// Микродоллары (1e-6) оказались слишком грубыми: вызов за $0.0000004
/// округлялся в 0 и терялся — та же болезнь, что numeric(12,6) (Issue #14).
pub const NANO: f64 = 1_000_000_000.0;

/// Перевести USD в нанодоллары (округление к ближайшему).
pub fn usd_to_nano(usd: f64) -> i64 {
    if !usd.is_finite() {
        return i64::MAX; // неопределённость трактуем как «очень дорого» → стоп
    }
    (usd * NANO).round() as i64
}

/// Политика бюджета воркера (конфиг; состояние не хранит).
#[derive(Debug, Clone, Copy)]
pub struct BudgetPolicy {
    /// Общий лимит расходов на процесс воркера, USD (env `MAX_TOTAL_COST_USD`).
    pub max_total_cost_usd: f64,
    /// Сколько подряд неудачных задач терпим до самоотключения воркера.
    pub max_consecutive_errors: u32,
}

impl Default for BudgetPolicy {
    fn default() -> Self {
        Self {
            max_total_cost_usd: 5.0,
            max_consecutive_errors: 5,
        }
    }
}

/// Жёсткие лимиты ОДНОГО прохода воркера (Issue #4).
///
/// Issue #4: «установить жёсткий предел: max_llm_calls, max_duration_sec,
/// max_cost_usd». Денежный лимит живёт в `BudgetPolicy` (Issue #3); здесь —
/// счётчики, которые останавливают сам ЦИКЛ процесса, а не отдельную задачу:
/// сколько LLM-вызовов сделано и сколько времени прошло с начала прохода.
///
/// `0` означает «без лимита» — это осознанный дефолт, чтобы штатный
/// долгоживущий воркер не менял поведение. Лимиты включаются явно.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RunLimits {
    /// Максимум LLM-вызовов за проход (0 — без лимита).
    pub max_llm_calls: u32,
    /// Максимум секунд с начала прохода (0 — без лимита).
    pub max_duration_sec: u64,
}

impl Default for RunLimits {
    fn default() -> Self {
        Self {
            max_llm_calls: 0,
            max_duration_sec: 0,
        }
    }
}

/// Почему проход остановлен.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RunStop {
    /// Сделано `made` вызовов при лимите `limit`.
    LlmCalls { made: u32, limit: u32 },
    /// Прошло `elapsed_sec` секунд при лимите `limit`.
    Duration { elapsed_sec: u64, limit: u64 },
}

impl RunStop {
    /// Строка для лога/артефакта.
    pub fn reason(&self) -> String {
        match self {
            RunStop::LlmCalls { made, limit } => {
                format!("run_limit: llm calls {made} >= {limit}")
            }
            RunStop::Duration { elapsed_sec, limit } => {
                format!("run_limit: duration {elapsed_sec}s >= {limit}s")
            }
        }
    }
}

impl RunLimits {
    /// Проверить пределы прохода ПЕРЕД очередным claim.
    ///
    /// `None` — можно продолжать; `Some(RunStop)` — пора останавливаться.
    /// Семантика «строго выше»: ровно на границе (`made == limit`) уже
    /// останавливаемся — так лимит `1` означает ровно один вызов.
    pub fn check(&self, llm_calls: u32, elapsed_sec: u64) -> Option<RunStop> {
        if self.max_llm_calls > 0 && llm_calls >= self.max_llm_calls {
            return Some(RunStop::LlmCalls {
                made: llm_calls,
                limit: self.max_llm_calls,
            });
        }
        if self.max_duration_sec > 0 && elapsed_sec >= self.max_duration_sec {
            return Some(RunStop::Duration {
                elapsed_sec,
                limit: self.max_duration_sec,
            });
        }
        None
    }
}

/// Причина блокировки. Отображается в `block_reason` и состояние задачи.
#[derive(Debug, Clone, PartialEq)]
pub enum BudgetBlock {
    /// Суммарные расходы превысили глобальный лимит.
    GlobalCap { spent_usd: f64, cap_usd: f64 },
    /// Задача исчерпала свой токен-бюджет.
    TaskCap { spent_tokens: i64, cap_tokens: i64 },
    /// F8: дерево (root_id) исчерпало суммарный бюджет root_budget_cap.
    RootCap { root_spent: i64, root_cap: i64 },
    /// Провайдер отверг ключ (401/403) — повторять бессмысленно.
    AuthFailure { status: u16 },
}

impl BudgetBlock {
    /// Строка для `block_reason` / артефакта.
    pub fn reason(&self) -> String {
        match self {
            BudgetBlock::GlobalCap { spent_usd, cap_usd } => format!(
                "budget_exhausted: global cap exceeded (spent ${spent_usd:.6} >= cap ${cap_usd:.6})"
            ),
            BudgetBlock::TaskCap {
                spent_tokens,
                cap_tokens,
            } => format!(
                "budget_exhausted: task cap exceeded ({spent_tokens} >= {cap_tokens} tokens)"
            ),
            BudgetBlock::RootCap {
                root_spent,
                root_cap,
            } => format!(
                "budget_exhausted: root tree cap exceeded ({root_spent} >= {root_cap} tokens)"
            ),
            BudgetBlock::AuthFailure { status } => {
                format!("auth_failed: LLM provider rejected credentials (HTTP {status})")
            }
        }
    }

    /// Целевое состояние задачи. Авторизационный сбой — отдельное состояние:
    /// он требует вмешательства оператора (ротация ключа), а не просто бюджета.
    pub fn state(&self) -> &'static str {
        match self {
            BudgetBlock::AuthFailure { .. } => "failed",
            _ => "budget_exhausted",
        }
    }
}

/// Глобальный лимит не превышен?
///
/// `spent_usd` — суммарная стоимость из ledger, `cap_usd` — лимит.
/// Сравнение в микродолларах: ровно на границе (`spent == cap`) ещё разрешаем,
/// блокируем строго при превышении — как `spent_tokens > budget_cap` в схеме.
pub fn global_budget_ok(spent_usd: f64, cap_usd: f64) -> bool {
    usd_to_nano(spent_usd) <= usd_to_nano(cap_usd)
}

/// Токен-бюджет задачи не исчерпан?
///
/// Семантика совпадает с `claim_task` (схема): задача берётся, пока
/// `spent_tokens < budget_cap`.
pub fn task_budget_ok(spent_tokens: i64, budget_cap: i64) -> bool {
    spent_tokens < budget_cap
}

/// HTTP-статус означает проблему с ключом/правами (повтор бессмысленен)?
pub fn is_auth_failure(status: Option<u16>) -> bool {
    matches!(status, Some(401) | Some(403))
}

/// Пора ли отключать воркер целиком (слишком много неудач подряд)?
pub fn should_disable(consecutive_errors: u32, max_consecutive_errors: u32) -> bool {
    max_consecutive_errors > 0 && consecutive_errors >= max_consecutive_errors
}

/// Проверить все предохранители перед вызовом LLM.
///
/// F8: кроме локального токен-бюджета задачи проверяется суммарный бюджет
/// дерева (`root_spent`/`root_budget`): `root_budget = None` означает, что
/// лимита по дереву нет. Блокируем строго на границе (`>=`), как гейты в SQL.
///
/// Возвращает `Err(BudgetBlock)` — вызывающий обязан НЕ звать LLM и
/// заблокировать задачу.
pub fn check_before_call(
    policy: &BudgetPolicy,
    spent_usd: f64,
    spent_tokens: i64,
    budget_cap: i64,
    root_spent: i64,
    root_budget: Option<i64>,
) -> Result<(), BudgetBlock> {
    if !task_budget_ok(spent_tokens, budget_cap) {
        return Err(BudgetBlock::TaskCap {
            spent_tokens,
            cap_tokens: budget_cap,
        });
    }
    if let Some(root_cap) = root_budget {
        if !task_budget_ok(root_spent, root_cap) {
            return Err(BudgetBlock::RootCap {
                root_spent,
                root_cap,
            });
        }
    }
    if !global_budget_ok(spent_usd, policy.max_total_cost_usd) {
        return Err(BudgetBlock::GlobalCap {
            spent_usd,
            cap_usd: policy.max_total_cost_usd,
        });
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn nano_roundtrip() {
        assert_eq!(usd_to_nano(1.0), 1_000_000_000);
        assert_eq!(usd_to_nano(0.000017), 17_000);
        assert_eq!(usd_to_nano(0.0), 0);
    }

    #[test]
    fn global_cap_blocks_strictly_above() {
        // На границе — разрешено (как spent_tokens < budget_cap).
        assert!(global_budget_ok(5.0, 5.0));
        assert!(global_budget_ok(4.999999, 5.0));
        // Строго выше — блок.
        assert!(!global_budget_ok(5.000001, 5.0));
        assert!(!global_budget_ok(6.0, 5.0));
    }

    #[test]
    fn tiny_costs_do_not_round_to_zero() {
        // Именно этот случай терялся при numeric(12,6) — здесь он ловится.
        assert!(!global_budget_ok(0.0000004, 0.0000001));
        assert!(global_budget_ok(0.0000001, 0.0000004));
    }

    #[test]
    fn task_cap_semantics_match_schema() {
        assert!(task_budget_ok(0, 100));
        assert!(task_budget_ok(99, 100));
        assert!(!task_budget_ok(100, 100));
        assert!(!task_budget_ok(101, 100));
    }

    #[test]
    fn auth_failures_are_401_403() {
        assert!(is_auth_failure(Some(401)));
        assert!(is_auth_failure(Some(403)));
        assert!(!is_auth_failure(Some(429)));
        assert!(!is_auth_failure(Some(500)));
        assert!(!is_auth_failure(None));
    }

    #[test]
    fn disable_after_max_consecutive() {
        assert!(!should_disable(4, 5));
        assert!(should_disable(5, 5));
        assert!(should_disable(6, 5));
        // 0 = никогда не отключать автоматически.
        assert!(!should_disable(100, 0));
    }

    #[test]
    fn check_prefers_task_cap_then_global() {
        let p = BudgetPolicy {
            max_total_cost_usd: 5.0,
            max_consecutive_errors: 5,
        };
        // Всё в порядке.
        assert_eq!(check_before_call(&p, 0.0, 0, 100, 0, None), Ok(()));
        // Исчерпан токен-бюджет задачи — это первое, что проверяем.
        assert!(matches!(
            check_before_call(&p, 0.0, 100, 100, 0, None),
            Err(BudgetBlock::TaskCap { .. })
        ));
        // F8: исчерпан бюджет дерева (локальный цел).
        assert!(matches!(
            check_before_call(&p, 0.0, 0, 100, 500, Some(500)),
            Err(BudgetBlock::RootCap { .. })
        ));
        // F8: лимита по дереву нет (None) — не блокирует.
        assert_eq!(check_before_call(&p, 0.0, 0, 100, 10_000, None), Ok(()));
        // Глобальный лимит.
        assert!(matches!(
            check_before_call(&p, 9.0, 0, 100, 0, None),
            Err(BudgetBlock::GlobalCap { .. })
        ));
    }

    #[test]
    fn run_limits_zero_means_unlimited() {
        let l = RunLimits::default();
        assert_eq!(l.check(0, 0), None);
        assert_eq!(l.check(10_000, 86_400), None);
    }

    #[test]
    fn run_limits_stop_on_llm_calls() {
        let l = RunLimits {
            max_llm_calls: 3,
            max_duration_sec: 0,
        };
        assert_eq!(l.check(2, 0), None);
        // Ровно на границе — уже стоп: лимит 1 = ровно один вызов.
        assert_eq!(l.check(3, 0), Some(RunStop::LlmCalls { made: 3, limit: 3 }));
        assert!(matches!(l.check(4, 0), Some(RunStop::LlmCalls { .. })));
    }

    #[test]
    fn run_limits_stop_on_duration() {
        let l = RunLimits {
            max_llm_calls: 0,
            max_duration_sec: 60,
        };
        assert_eq!(l.check(0, 59), None);
        assert_eq!(
            l.check(0, 60),
            Some(RunStop::Duration {
                elapsed_sec: 60,
                limit: 60
            })
        );
    }

    #[test]
    fn run_limits_llm_calls_checked_first() {
        let l = RunLimits {
            max_llm_calls: 1,
            max_duration_sec: 1,
        };
        // Оба предела достигнуты — приоритет у вызовов (детерминизм сообщения).
        assert!(matches!(l.check(1, 1), Some(RunStop::LlmCalls { .. })));
    }

    #[test]
    fn run_stop_reason_is_descriptive() {
        assert!(RunStop::LlmCalls { made: 5, limit: 5 }
            .reason()
            .starts_with("run_limit: llm calls"));
        assert!(RunStop::Duration {
            elapsed_sec: 30,
            limit: 30
        }
        .reason()
        .starts_with("run_limit: duration"));
    }

    #[test]
    fn reason_and_state_are_stable() {
        let g = BudgetBlock::GlobalCap {
            spent_usd: 6.0,
            cap_usd: 5.0,
        };
        assert!(g.reason().starts_with("budget_exhausted"));
        assert_eq!(g.state(), "budget_exhausted");

        let a = BudgetBlock::AuthFailure { status: 401 };
        assert!(a.reason().starts_with("auth_failed"));
        assert_eq!(a.state(), "failed");
    }
}

//! Ошибки LLM-worker.

use thiserror::Error;

#[derive(Debug, Error)]
pub enum WorkerError {
    #[error("worker config error: {0}")]
    Config(String),

    #[error("database error: {0}")]
    Database(#[from] swarm_core::DispatcherError),

    #[error("llm error: {0}")]
    Llm(#[from] swarm_llm::LlmError),

    #[error("artifact error: {0}")]
    Artifact(String),

    #[error("budget exhausted before LLM call")]
    BudgetExhausted,

    #[error("lease lost during work")]
    LeaseLost,

    // ---- v0.4: shell tools + sandbox (Волна 5: гейт снят) ----
    /// WK004: команда не прошла allowlist (ТЗ v0.4 §4).
    #[error("WK004 allowlist rejected: {reason} (command: {command:?})")]
    AllowlistRejected { command: String, reason: String },

    /// WK005: команда превысила таймаут (ТЗ v0.4 §5).
    #[error("WK005 command timeout after {timeout_sec}s: {command:?}")]
    CommandTimeout { command: String, timeout_sec: u64 },

    /// Ошибка sandbox-контейнера (Docker).
    #[error("sandbox error: {0}")]
    Sandbox(String),

    /// Исчерпан бюджет итераций Agent Loop (ТЗ v0.4 §6).
    #[error("agent loop exceeded max iterations ({max})")]
    MaxIterations { max: u32 },

    /// LLM вернул невалидный tool call.
    #[error("invalid tool call from llm: {0}")]
    InvalidToolCall(String),
}

pub type Result<T> = std::result::Result<T, WorkerError>;

